'use strict';
(function(){
const D=globalThis.RA.D;
const q=(prompt,answer,d1,d2,explain,sense=1,type='meaning')=>({prompt,answer,d1,d2,explain,sense,type});
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({errorType,wrong,right,reason});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:'Etymonline: https://www.etymonline.com/word/'+w.toLowerCase().replaceAll(' ','-')});
const P=(w,origin,c,m,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(c)?c:[c],mistakes:[m],quiz:qs.map((x,i)=>({id:w+'.q'+(i+1),senseId:w+'.s'+x.sense,type:'辨义与用法',prompt:x.prompt,options:[x.answer,x.d1,x.d2],answer:x.answer,explain:x.explain,errorType:x.type}))});
P('remind','Remind came through Old French remembrer from Latin rememorari, “remember again”; it can prompt someone to act or make someone think of another thing.',[C('remind.s1','提醒','Please remind me to submit the travel form before the office closes on Friday.','请提醒我在周五办公室下班前提交差旅表。','Please remind me / to submit the travel form / before the office closes.','remind.s1 常用 remind someone to do something，表示提醒某人去做某事。','说话者请求对方提醒自己提交表格。'),C('remind.s2','使想起','The smell of cedar reminded her of the wooden cabin where she had spent summers as a child.','雪松的气味让她想起童年夏天住过的木屋。','The smell of cedar reminded her / of the wooden cabin / from childhood summers.','remind.s2 常用 remind someone of something，表示使某人想起某事。','气味触发了童年木屋的回忆。')],M('Please remind me submitting the travel form, but do not tell me or prompt me to do it.','Please remind me to submit the travel form before Friday.','表示提醒某人去做事时，常用 remind someone to do something。','grammar'),[q('What does the speaker ask to be reminded to do?','submit the travel form','close the office','book a cabin','说话者要提交差旅表。',1,'context'),q('What reminded her of the childhood cabin?','the smell of cedar','the Friday office schedule','a travel form','雪松气味使她想起童年木屋。',2,'context'),q('Which pattern means “prompt someone to act”?','remind someone to do something','remind someone from doing something','remind something to someone of','remind someone to do something 表示提醒某人去做。',1,'grammar'),q('Which meaning is used in “That song reminds me of school”?','makes me think of school','prompts me to attend school tomorrow','records my school attendance','这里 reminds me of 表示使我想起学校。',2,'meaning')]);
P('reminder','Reminder is formed from remind and -er; it can be a prompt to do something or an object that brings a person or event to mind.',[C('reminder.s1','提醒；提示','She set a phone reminder to renew her library card before it expired.','她设置了手机提醒，以便在图书证过期前续期。','She set a phone reminder / to renew the library card / before it expired.','reminder.s1 指提示人们记得做某事的通知或物件。','手机提醒帮助她及时续期。'),C('reminder.s2','引起回忆的东西','The faded concert ticket was a reminder of the night the two friends first met.','褪色的音乐会门票让人想起两位朋友初次相遇的那个夜晚。','The faded ticket was a reminder / of the night / the friends first met.','reminder.s2 指使人想起某段经历、人物或事件的事物。','旧门票唤起了初次相遇的回忆。')],M('She set a reminder to renew her card by deleting the alert before the expiration date.','She set a reminder to renew her card before the expiration date.','删除提醒会让人更容易忘记续期，而不是帮助记住。','meaning'),[q('What did she set the phone reminder to do?','renew her library card','remember the concert ticket','contact the person who issued it','手机提醒她续借图书证。',1,'context'),q('What did the old ticket remind the friends of?','the night they first met','the library card’s expiration date','a phone alarm','旧门票让朋友想起初次相遇的夜晚。',2,'context'),q('Which item is a reminder to act?','a calendar alert for a dentist appointment','a photograph of a childhood home','a souvenir from a concert','牙医预约日历提醒是提示行动的 reminder。',1,'meaning'),q('Which item is a reminder of an event?','a faded ticket from the concert where they met','a phone alert set for tomorrow','a checklist of tasks not yet done','旧音乐会门票是那次相遇的回忆物。',2,'meaning')]);
P('reminiscent','Reminiscent comes from Latin reminisci, “remember”; it can describe something that evokes a similar thing or someone’s reflective, nostalgic manner.',[C('reminiscent.s1','使人想起……的','The new bakery’s cinnamon rolls were reminiscent of the ones her grandmother used to make.','新面包店的肉桂卷让她想起祖母以前做的那种。','The cinnamon rolls were reminiscent of / the ones her grandmother / used to make.','reminiscent.s1 常用 reminiscent of，表示某物使人联想到相似的人或事。','味道使她联想到祖母的烘焙。'),C('reminiscent.s2','怀旧的；追忆的','He grew reminiscent as he described the neighborhood where he had played as a child.','描述童年玩耍的街区时，他的语气变得怀旧。','He grew reminiscent / while describing the neighborhood / of his childhood.','reminiscent.s2 可描述回想过去、流露怀旧情绪的人。','谈起童年街区让他沉浸于回忆。')],M('The cinnamon rolls were reminiscent from her grandmother, although reminiscent of is the required pattern for a comparison.','The cinnamon rolls were reminiscent of the ones her grandmother used to make.','表示使人想起某事时使用 reminiscent of，而不是 reminiscent from。','grammar'),[q('What did the bakery’s rolls resemble?','the ones her grandmother used to make','the phone reminder on her calendar','the neighborhood’s new buildings','新面包店的肉桂卷让她想起祖母做的点心。',1,'context'),q('How did he sound while describing his childhood neighborhood?','nostalgic and reflective','angry about a current bill','unable to recognize the street','他谈童年街区时语气怀旧。',2,'context'),q('Which pattern is standard?','reminiscent of a familiar song','reminiscent from a familiar song','reminiscent with a familiar song','reminiscent of 是常用搭配。',1,'grammar'),q('What does reminiscent mean in “a reminiscent tone”?','showing thought about the past','prompting someone to complete a task','far away from a town','a reminiscent tone 指流露追忆往事的语气。',2,'meaning')]);
P('remiss','Remiss came from Latin remissus, “relaxed or slack”; it describes failing to do one’s duty or failing to be careful enough.',C('remiss.s1','疏忽的；失职的','The inspector would be remiss not to test the alarm after replacing its battery.','更换电池后如果不测试警报，检查员就算失职。','The inspector would be remiss / not to test the alarm / after replacing its battery.','remiss 指未尽职责或不够谨慎。','更换电池后应测试设备，忽略这一步就是疏忽。'),M('The inspector was remiss in her duties because she carefully tested every alarm and documented each result.','The inspector was diligent because she tested every alarm and documented each result.','认真检查并记录结果是尽职，不能据此称为 remiss。','meaning'),[q('What should the inspector test after replacing the battery?','the alarm','the rent agreement','the concert ticket','检查员更换电池后应测试警报。'),q('When would she be remiss?','if she failed to test the alarm','if she documented the test carefully','if the alarm worked correctly','未测试警报就会构成疏忽。',1,'context'),q('What does remiss mean?','careless about a duty','careful and thorough','nostalgic about childhood','remiss 指疏忽职责或不够谨慎。',1,'meaning'),q('Which phrase naturally follows remiss?','remiss in one’s duties','remiss to a phone reminder of','remiss at a distant cabin','remiss in one’s duties 是自然搭配。',1,'collocation')]);
P('remit','Remit comes from Latin remittere, “send back”; it can send money, officially cancel a debt or penalty, or name an assigned area of responsibility.',[C('remit.s1','汇出（款项）','The overseas customer remitted the invoice payment to the supplier before the shipment left port.','海外客户在货物离港前把发票款汇给供应商。','The customer remitted the payment / to the supplier / before shipment.','remit.s1 指把款项汇给异地的收款人。','客户在发货前汇出货款。'),C('remit.s2','免除；赦免','The council voted to remit the late fee because the billing notice had been sent to the wrong address.','账单通知寄错地址后，委员会投票决定免除滞纳金。','The council voted to remit the fee / because the notice / went to the wrong address.','remit.s2 指正式免除债务、费用或惩罚。','因通知寄错，滞纳金被免除。'),C('remit.s3','职权范围；职责','The review panel’s remit was limited to checking safety procedures, not deciding the contractor’s pay.','审查小组的职责范围仅限于检查安全程序，不包括决定承包商的报酬。','The panel’s remit was limited / to checking safety procedures / rather than setting pay.','remit.s3 作名词指正式交付给个人或团体的职责范围。','小组只负责审查安全程序。')],M('The council remitted the late fee by adding it to the customer’s bill and requiring immediate payment.','The council remitted the late fee by officially canceling it.','免除费用意味着取消应付款，而不是把费用加到账单上。','meaning'),[q('What did the overseas customer remit?','the invoice payment','the supplier’s safety duties','the council’s late fee','客户向供应商汇出了发票款。',1,'context'),q('Why did the council remit the late fee?','the billing notice went to the wrong address','the customer paid the fee twice','the panel had no authority to review safety','通知寄错地址后，委员会免除了滞纳金。',2,'context'),q('What was the review panel’s remit?','checking safety procedures','setting the contractor’s pay','sending payments overseas','小组的职权范围是检查安全程序。',3,'context'),q('Which meaning of remit is used in “the judge remitted the fine”?','officially canceled it','sent the money to another country','defined the panel’s area of work','judge remitted the fine 指法官免除罚款。',2,'meaning')]);
P('remittance','Remittance is formed from remit and -ance; it is a payment sent from one place to another, often across a national border.',C('remittance.s1','汇款','Each month, the nurse sent a remittance to her parents so they could pay household expenses.','护士每月给父母汇款，帮助他们支付家庭开支。','The nurse sent a remittance / to her parents / for household expenses.','remittance 指从一个地方汇到另一个地方的一笔款项。','她定期汇款帮助父母支付生活费。'),M('The bank labeled the nurse’s remittance as money she received from her parents, although she had sent it to them.','The bank labeled the payment she sent to her parents a remittance.','remittance 是汇出的一笔钱；语境中的护士是汇款人。','meaning'),[q('Who received the nurse’s remittance?','her parents','the hospital’s review panel','the overseas supplier','护士的父母收到她汇去的钱。'),q('How often did she send the payment?','each month','once after a concert','only when the fee was canceled','她每月给父母汇款。',1,'context'),q('What is a remittance?','a payment sent from one place to another','a fee officially canceled','a task assigned to a committee','remittance 指汇往别处的一笔款项。',1,'meaning'),q('Which suffix is used in remittance?','-ance','-ive','-less','remit 加 -ance 构成 remittance。',1,'word-formation')]);
P('remnant','Remnant came through Old French remenant, “what remains”; it can mean a leftover piece or, in commerce, a short piece of cloth left from a larger length.',[C('remnant.s1','残余；剩余部分','A remnant of the old stone wall remained beside the new road after most of the structure was cleared.','大部分石墙拆除后，新路旁还留着一小段旧墙。','A remnant of the wall remained / beside the new road / after demolition.','remnant.s1 指大部分被移除或用掉后剩下的一小部分。','旧墙拆除后仍留下一小段。'),C('remnant.s2','零头布；零料','The tailor used a remnant of blue wool to patch the elbow of the child’s coat.','裁缝用一块蓝色羊毛布零料补上孩子外套的肘部。','The tailor used a wool remnant / to patch / the coat’s elbow.','remnant.s2 常指商店出售或用于缝补的余布。','布料剩片被用来补衣服。')],M('The tailor called a full, uncut bolt of new wool a remnant left over after the fabric had been used.','The tailor used a small leftover remnant of wool to patch the coat.','remnant 指用剩后留下的小块材料，不是完整新布卷。','meaning'),[q('What remained beside the new road?','a small part of the old stone wall','the entire original wall','a wool coat on display','道路旁留下了一小段旧墙。',1,'context'),q('What did the tailor do with the wool remnant?','patched the child’s coat','built the stone wall','sent an invoice payment','裁缝用余布补了孩子的外套。',2,'context'),q('Which item is a remnant of fabric?','a short leftover piece from a bolt','a full new bolt not yet cut','a complete winter coat','布卷裁剩的一小块是 remnant。',2,'meaning'),q('What does remnant generally mean?','a small part left after most is gone','a fee canceled by a council','a planned meeting place','remnant 指大部分消失后留下的部分。',1,'meaning')]);
P('remodel','Remodel combines re- and model; it means alter a building’s design or structure so it works or looks different.',C('remodel.s1','改建；改造','The owners remodeled the kitchen by moving the sink and widening the doorway for easier access.','房主通过移动水槽、加宽门口来改造厨房，使其更方便使用。','The owners remodeled the kitchen / by moving the sink / and widening the doorway.','remodel 指改变建筑或房间的设计、结构或外观。','厨房布局经过改造以便通行。'),M('The owners remodeled the kitchen by leaving every fixture and wall unchanged and making no alterations.','The owners remodeled the kitchen by changing its layout and widening the doorway.','remodel 表示改造；完全不作改变就不能称为 remodel。','meaning'),[q('What did the owners change in the kitchen?','the sink location and doorway width','the parents’ monthly remittance','the house’s distance from town','房主移动了水槽并加宽门口。',1,'context'),q('What does remodel mean?','alter a building’s design or structure','send money to a distant supplier','remember a childhood event','remodel 指改造建筑的设计或结构。',1,'meaning'),q('Which project is a remodel?','changing a kitchen layout and adding storage','cleaning the kitchen without changing it','renaming the kitchen but leaving it as is','改动厨房布局并加储物空间属于改建。',1,'context'),q('What does re- contribute to remodel?','again or anew','far away','without care','re- 表示重新设计或改造。',1,'word-formation')]);
P('remorse','Remorse came from Old French remors and Latin remordere, “bite back”; it means deep guilt or sorrow for a wrong one has done.',C('remorse.s1','悔恨；内疚','He felt remorse for hiding the mistake and went back to tell his supervisor the full story.','他因隐瞒错误而感到悔恨，于是回去向主管说明了全部经过。','He felt remorse / for hiding the mistake / and told his supervisor the truth.','remorse 指对自己做错的事感到强烈内疚或悔恨。','悔恨促使他坦白错误。'),M('She showed remorse for the damage by laughing about it and refusing to acknowledge what she had done.','She showed remorse for the damage by apologizing and offering to repair it.','承认错误、道歉并补救体现悔恨；嘲笑且否认则不然。','meaning'),[q('Why did he feel remorse?','he had hidden a mistake','he had remodeled the kitchen','he had sent a remittance on time','他因隐瞒错误而感到悔恨。'),q('What did he do after feeling remorse?','told his supervisor the full story','continued hiding the mistake','dismissed his supervisor','他回去向主管坦白了全部经过。',1,'context'),q('What does remorse mean?','deep guilt for a wrong one has done','a slight chance of rain','a planned meeting','remorse 指因做错事而深感内疚。',1,'meaning'),q('Which action most clearly shows remorse?','apologizing and repairing the damage','denying responsibility and laughing','asking someone to remember a task','道歉并修复损害体现悔恨。',1,'context')]);
P('remote','Remote comes from Latin remotus, “removed or distant”; it can mean far away in place or time, very unlikely, or emotionally detached.',[C('remote.s1','遥远的；偏僻的','A remote village in the mountains receives deliveries only twice a week because the road is narrow.','山中偏僻村庄每周只收到两次配送，因为道路狭窄。','A remote village receives deliveries / only twice a week / because its road is narrow.','remote.s1 指空间上距离远或不易到达的。','村庄偏远，道路限制了配送频率。'),C('remote.s2','久远的；关系远的','She found a remote reference to the family in a letter written nearly two centuries earlier.','她在一封近两百年前的信中发现了一条关于家族的久远记载。','She found a remote reference / in a letter / written nearly two centuries earlier.','remote.s2 可指时间久远，也可指关系疏远。','信件提供了久远的家族记载。'),C('remote.s3','可能性极小的','There is only a remote chance that the package will arrive before the office closes today.','包裹今天在办公室关门前送到的可能性极小。','There is a remote chance / the package will arrive / before closing.','remote.s3 表示某事发生的可能性很小。','今天及时送达的概率很低。'),C('remote.s4','冷淡的；疏远的','Although they worked in the same office, he remained remote and rarely spoke to his colleagues.','尽管在同一间办公室工作，他仍显得冷淡，很少与同事交谈。','He remained remote / and rarely spoke / to his colleagues.','remote.s4 描述态度冷淡、不亲近或情感疏远。','他与同事保持距离。')],M('There was a remote chance of delivery, meaning the package was certain to arrive before the office closed.','There was only a remote chance of delivery, so arrival before closing was unlikely.','remote chance 表示可能性很小，不是必然发生。','meaning'),[q('How often did the remote village receive deliveries?','twice a week','every hour','only once every two centuries','偏远村庄每周收到两次配送。',1,'context'),q('How old was the letter with the remote family reference?','nearly two centuries','two weeks','one year','信件写于近两百年前。',2,'context'),q('What are the chances the package arrives before closing?','very small','certain','exactly one hundred percent','remote chance 表示送达概率很小。',3,'context'),q('How did the man act toward colleagues?','coldly and at a distance','warmly and talkative','with strong remorse','他对同事显得冷淡疏远。',4,'context')]);
P('removal','Removal is formed from remove and -al; it means taking something away or the process of moving from one home to another.',[C('removal.s1','移除；清除','The safe removal of asbestos required trained workers, sealed equipment and a temporary closure of the building.','安全清除石棉需要受训工人、密封设备，并暂时关闭建筑。','The safe removal of asbestos required / trained workers / and sealed equipment.','removal.s1 指把物体或物质从某处移走。','石棉清除需要专业人员和密封设备。'),C('removal.s2','搬迁；搬家','The family arranged a removal van for Saturday so their furniture could be taken to the new apartment.','一家人安排周六使用搬家货车，把家具运到新公寓。','The family arranged a removal van / to move the furniture / on Saturday.','removal.s2 指从一所住宅搬到另一所住宅的过程。','搬家货车运送家具到新住处。')],M('The removal of asbestos was completed safely by spreading the fibers through occupied rooms.','The removal team sealed off the area and safely took the asbestos out of the building.','清除石棉必须避免纤维扩散，不能把它散布到有人使用的房间。','meaning'),[q('What did trained workers remove from the building?','asbestos','the family’s furniture','the apartment’s name','工人负责安全清除石棉。',1,'context'),q('When did the family book the removal van?','for Saturday','after moving into the old house','before buying any furniture','一家人把搬家安排在周六。',2,'context'),q('Which removal means household relocation?','booking a van to move furniture to a new home','taking asbestos out of a sealed area','removing a stain from a shirt','搬运家具到新家属于搬家义 removal。',2,'meaning'),q('Which suffix forms removal from remove?','-al','-er','-ish','remove 加 -al 构成 removal。',1,'word-formation')]);
P('remove','Remove comes from Latin removere, “move back or away”; it can take something away, get rid of something unwanted, dismiss a person, or formally take off clothing.',[C('remove.s1','移走；拿走','Please remove the package from the doorway so wheelchair users can pass safely.','请把包裹从门口移开，让轮椅使用者安全通行。','Please remove the package / from the doorway / so everyone can pass.','remove.s1 指把东西从原处移走。','移开包裹可保持通道畅通。'),C('remove.s2','去除；消除','The technician used a solvent to remove the label residue from the glass jar.','技师用溶剂去除玻璃罐上的标签残胶。','The technician used solvent / to remove residue / from the jar.','remove.s2 指清除污迹、物质或不想要的东西。','溶剂清除了玻璃上的残胶。'),C('remove.s3','免职；开除','The board voted to remove the director after an independent investigation confirmed repeated financial misconduct.','独立调查确认多次财务不当行为后，董事会投票罢免了主管。','The board voted to remove the director / after an investigation / confirmed misconduct.','remove.s3 指正式解除某人的职位。','董事会依据调查结果罢免主管。'),C('remove.s4','脱下（衣服，正式）','Visitors were asked to remove their muddy boots before entering the restored gallery.','参观者进入修复后的展厅前被要求脱掉沾满泥的靴子。','Visitors were asked to remove their boots / before entering / the restored gallery.','remove.s4 可正式表示脱下衣物或鞋子。','参观者需在进入展厅前脱靴。')],M('The visitor removed her muddy boots by putting them on and tying the laces more tightly.','The visitor removed her muddy boots by taking them off before entering the gallery.','remove boots 指脱掉靴子，而不是穿上并系紧。','meaning'),[q('What did the visitor move away from the doorway?','a package','a director from the board','a stain from a jar','包裹被从门口移开。',1,'context'),q('What did the technician remove from the jar?','label residue','a director','muddy boots','技师去除了标签残胶。',2,'context'),q('Why did the board remove the director?','an investigation confirmed financial misconduct','the director had removed a stain','the gallery needed a new doorway','调查确认财务不当行为后，董事会罢免主管。',3,'context'),q('What were visitors asked to remove before entering?','their muddy boots','the gallery’s glass jars','the board’s director','进入展厅前参观者要脱掉泥靴。',4,'context')]);
P('remuneration','Remuneration comes from Latin remuneratio, “a rewarding”; it means payment for work or a reward given in return for service or loss.',[C('remuneration.s1','劳动报酬','The contract specifies the consultant’s remuneration for each day of work and lists travel expenses separately.','合同规定了顾问每天的劳动报酬，并将差旅费另行列出。','The contract specifies remuneration / for each workday / separately from travel expenses.','remuneration.s1 指为工作或服务支付的钱。','合同列明每日劳动报酬。'),C('remuneration.s2','酬谢；补偿金','The town offered remuneration to residents whose gardens were damaged during the drainage project.','排水工程损坏了居民的花园后，小镇向他们提供补偿金。','The town offered remuneration / to residents / for project damage.','remuneration.s2 可指为感谢帮助或弥补损失而支付的酬谢或补偿。','居民因工程损失获得补偿。')],M('The consultant’s remuneration was the unpaid bill she owed the company for doing no work.','The consultant’s remuneration was the payment the company owed for her completed services.','remuneration 是因工作或服务而获得的报酬，不是员工欠雇主的钱。','meaning'),[q('How does the contract calculate the consultant’s remuneration?','for each day of work','as a share of the residents’ garden damage','by counting phone reminders','合同按顾问工作天数规定报酬。',1,'context'),q('Why did residents receive remuneration?','their gardens were damaged by the project','they failed to pay the consultant','they were removed from the contract','工程损坏花园后，居民获得了补偿。',2,'context'),q('What does remuneration usually mean?','payment for work or services','a formal apology for an error','an old memory of a person','remuneration 通常指工作或服务报酬。',1,'meaning'),q('Which phrase is natural?','annual remuneration for the role','remuneration of the reminder to the office','remuneration the damaged garden away','annual remuneration for the role 是自然搭配。',1,'collocation')]);
P('renaissance','Renaissance came from French renaissance, “rebirth”; it names the European cultural period of the 14th–17th centuries or a renewed flourishing of activity.',[C('renaissance.s1','文艺复兴','The lecture traced how Renaissance artists studied perspective, anatomy and classical Greek sculpture.','讲座介绍了文艺复兴艺术家如何研究透视法、解剖学和古希腊雕塑。','The lecture traced Renaissance artists / studying perspective / and classical sculpture.','renaissance.s1 指欧洲约14至17世纪艺术与学术繁荣的历史时期。','艺术家重新研究古典艺术与科学。'),C('renaissance.s2','复兴；再度繁荣','The old theater experienced a renaissance after volunteers restored the stage and began hosting local plays.','志愿者修复舞台并开始举办本地戏剧后，老剧院重新焕发生机。','The theater experienced a renaissance / after volunteers restored the stage / and hosted plays.','renaissance.s2 比喻某项活动或兴趣重新兴盛。','修复后剧院活动再次繁荣。')],M('The theater experienced a renaissance by closing permanently and ending every performance.','The theater experienced a renaissance when restoration brought performances and audiences back.','renaissance 比喻重新兴盛；永久关闭、停止演出与复兴相反。','meaning'),[q('What topics did Renaissance artists study in the lecture?','perspective, anatomy and classical sculpture','remittance fees and rent agreements','modern phone reminders','讲座讨论了艺术家对透视、解剖和古典雕塑的研究。',1,'context'),q('What happened after volunteers restored the old theater?','it began hosting local plays again','it closed permanently','it became a remote village','老剧院修复后重新举办本地戏剧。',2,'context'),q('Which use is the historical period?','Renaissance art in Europe from the 14th to 17th centuries','a modern revival of a local theater','a reminder of a childhood event','14至17世纪欧洲的文艺复兴是历史时期义。',1,'meaning'),q('What does the French source renaissance mean?','rebirth','removal','payment','renaissance 源自法语，意为“重生、复兴”。',1,'word-formation')]);
P('rename','Rename combines re- and name; it means change the name by which a person, place or thing is known.',C('rename.s1','改名','The council voted to rename the riverside park after a local teacher who had organized free lessons for decades.','委员会投票决定以一位数十年来组织免费课程的当地教师为河滨公园重新命名。','The council voted to rename the park / after a local teacher / who organized free lessons.','rename 指改变某人、地点或事物的名称。','公园将以当地教师的名字命名。'),M('The council renamed the park by keeping its old name unchanged and refusing to choose another one.','The council renamed the park after the local teacher.','改名意味着采用一个新的名字；保留旧名不变不算改名。','meaning'),[q('Who was the riverside park named after?','a local teacher','the council’s remote village','the person who sent a remittance','公园以当地教师命名。'),q('What had the teacher organized for decades?','free lessons','rent removals','Renaissance lectures only','这位教师数十年来组织免费课程。',1,'context'),q('What does rename mean?','change the name something is known by','remember someone’s former name','remove an object from a place','rename 指改变名称。',1,'meaning'),q('What does re- mean in rename?','again or anew','far away','without a name','rename 中 re- 表示重新命名。',1,'word-formation')]);
P('rend','Rend is recorded in English for tearing violently; its deeper history is uncertain. It can tear material apart or split a group through conflict.',[C('rend.s1','猛撕；撕碎','The storm rent the sail along its weakest seam, leaving the crew to steer the boat toward shore.','风暴沿着最脆弱的接缝撕裂了船帆，船员只得把船驶向岸边。','The storm rent the sail / along its weakest seam / and the crew turned toward shore.','rend.s1 指猛烈地撕裂布、纸或帆等材料。','风暴把船帆撕开。'),C('rend.s2','使分裂；使分开','The bitter dispute rent the small committee into two opposing groups that could no longer agree on a plan.','激烈争端使小委员会分裂成两个对立团体，双方再也无法就方案达成一致。','The dispute rent the committee / into opposing groups / that could not agree.','rend.s2 比喻冲突使群体或关系分裂。','争端将委员会分成对立阵营。')],M('The storm rent the sail by smoothing every tear and leaving the fabric completely intact.','The storm rent the sail by tearing it along a weak seam.','rend 表示猛烈撕裂，不是修补或保持布料完整。','meaning'),[q('What happened to the sail?','the storm tore it along a weak seam','the crew renamed it after a teacher','the storm repaired it completely','风暴沿着接缝撕裂了船帆。',1,'context'),q('How did the dispute affect the committee?','it split the members into opposing groups','it helped them agree immediately','it removed the committee’s name','争端使委员会分裂成对立团体。',2,'context'),q('What does rend mean literally?','tear something violently','make something recognizable','pay someone for their work','rend 的字面义是猛烈撕裂。',1,'meaning'),q('What does rend mean figuratively?','divide a group through conflict','change a building’s design','send a payment to another place','rend 可比喻冲突使群体分裂。',2,'meaning')]);
P('render','Render came through Old French rendre from Latin reddere, “give back”; it can cause a state, provide service, translate or perform, or coat a wall with plaster.',[C('render.s1','致使；使变得','The sudden shutdown rendered the old scanner useless until technicians replaced its control board.','突然停机使旧扫描仪无法使用，直到技师更换了控制板。','The shutdown rendered the scanner useless / until technicians / replaced its board.','render.s1 常用于 render something + 形容词，表示使某物变成某状态。','停机使扫描仪无法工作。'),C('render.s2','给予；提供','The volunteer team rendered first aid to the cyclist while another member called emergency services.','一名志愿者呼叫急救服务时，队员们为骑行者提供了急救。','The team rendered first aid / while another member / called emergency services.','render.s2 指提供帮助、服务或正式决定。','志愿者为受伤骑行者提供急救。'),C('render.s3','翻译；表现；演奏','The choir rendered the old folk song in a new arrangement that kept its melody but changed the rhythm.','合唱团以新编曲演绎了这首民歌，保留旋律但改变节奏。','The choir rendered the folk song / in a new arrangement / with a changed rhythm.','render.s3 指以某种语言或艺术形式表达、翻译或演绎。','合唱团用新编曲演绎民歌。'),C('render.s4','粉刷；抹灰','Builders rendered the exterior wall with a smooth coat of cement before painting it.','建筑工人在粉刷前给外墙抹了一层平整的水泥。','Builders rendered the wall / with a smooth cement coat / before painting.','render.s4 在建筑中指给墙面抹灰或涂覆一层材料。','外墙先抹水泥再粉刷。')],M('The outage rendered the scanner useful because the machine stopped working and could not process any images.','The outage rendered the scanner useless because it could not process images.','render something useful 表示使其有用；设备停机并不能处理图像使其无用。','meaning'),[q('What rendered the scanner useless?','a shutdown before its control board was replaced','a volunteer’s first-aid kit','the choir’s new arrangement','扫描仪因停机和控制板故障而无法使用。',1,'context'),q('What service did the volunteer team render?','first aid','a wall coating','a translated song','志愿者队伍提供了急救。',2,'context'),q('How did the choir render the folk song?','in a new arrangement with a changed rhythm','as a cement coating on a wall','as a scanner repair invoice','合唱团以新编曲演绎了民歌。',3,'context'),q('What did builders render before painting?','the exterior wall with cement','the folk song into another language','the scanner useless','建筑工人给外墙抹了水泥。',4,'context')]);
P('rendering','Rendering is formed from render and -ing; it can mean a particular artistic performance or a particular translation or version of a text.',[C('rendering.s1','演绎；表现','The quartet’s rendering of the familiar hymn was slower than the original but preserved its central melody.','四重奏对这首熟悉赞美诗的演绎比原版慢，但保留了核心旋律。','The quartet’s rendering was slower / but preserved / the hymn’s main melody.','rendering.s1 指对音乐、角色或艺术作品的一种具体演绎方式。','演奏者保留旋律但调整了速度。'),C('rendering.s2','译文；版本','The translator compared two English renderings of the poem before choosing the one with the closest rhythm.','译者比较了这首诗的两个英文译本，最后选择了节奏最接近的一个。','The translator compared two renderings / before choosing / the closer rhythm.','rendering.s2 指文本的一种具体翻译或表达版本。','译者比较了两个英文版本。')],M('The translator called the text a rendering even though no version or translation had been produced.','The translator compared two renderings, each a different English version of the poem.','rendering 作译文义需要有一个具体的翻译版本。','meaning'),[q('How did the quartet perform the hymn?','more slowly than the original while keeping its melody','as a new English translation','with a cement finish on a wall','四重奏演绎较慢，但保留了旋律。',1,'context'),q('What did the translator compare?','two English versions of the poem','two concrete wall coatings','two remote villages','译者比较了两个英文译本。',2,'context'),q('What does rendering mean in music?','a particular performance or interpretation','a payment for a service','a room used for dining','音乐中的 rendering 指具体演绎方式。',1,'meaning'),q('What does rendering mean in translation?','a particular translated version','a choir’s tempo only','the act of removing a word','翻译中的 rendering 指某个译文版本。',2,'meaning')]);
P('rendezvous','Rendezvous came from French rendez-vous, “present yourselves”; it names a planned meeting or the agreed place for meeting.',C('rendezvous.s1','会合；约会地点','The two research boats chose a rendezvous near the lighthouse before continuing together toward the island.','两艘研究船约定在灯塔附近会合，然后结伴前往岛屿。','The boats chose a rendezvous / near the lighthouse / before sailing together.','rendezvous 指预先约定的会面，也可指会面的地点。','两艘船约在灯塔附近碰头。'),M('The boats missed their rendezvous because they met at the agreed lighthouse at the scheduled time.','The boats missed their rendezvous because one arrived at the lighthouse after the agreed time.','在约定地点和时间按时见面不是错过会合。','meaning'),[q('Where did the research boats plan their rendezvous?','near the lighthouse','at the remittance office','inside the old theater','研究船计划在灯塔附近会合。'),q('What did they do after meeting?','continued together toward the island','returned separately to the mainland','rendered a song for the harbor','会合后两艘船结伴前往岛屿。',1,'context'),q('What is a rendezvous?','a planned meeting or its agreed place','a payment sent across a border','a distant chance of success','rendezvous 指预定会面或会面地点。',1,'meaning'),q('Which French expression is rendezvous from?','rendez-vous, “present yourselves”','remettre, “send money”','reclus, “shut away”','rendezvous 来自法语 rendez-vous。',1,'word-formation')]);
P('rendition','Rendition is related to render; it can mean an artistic performance, a translated version, or the transfer of a suspect to another country for questioning.',[C('rendition.s1','（艺术）演绎；表演','Her live rendition of the jazz standard used a soft piano introduction and a faster final chorus.','她现场演绎爵士标准曲时，以轻柔的钢琴前奏开场，最后一段副歌速度更快。','Her rendition used a soft introduction / and a faster / final chorus.','rendition.s1 指歌曲、角色或故事的一次具体表演。','现场演唱对曲目作了独特处理。'),C('rendition.s2','译文；译本','The editor chose a new rendition of the poem because it preserved both the image and the original line breaks.','编辑选择了这首诗的新译本，因为它既保留意象，也保留了原诗的分行。','The editor chose a rendition / preserving the image / and original line breaks.','rendition.s2 指某文本的翻译版本。','译本保留了意象和原有分行。'),C('rendition.s3','引渡移交（尤指秘密引渡）','The report criticized the rendition of the suspect to another country without a public court hearing.','报告批评在没有公开法庭听证的情况下把嫌疑人移交到另一个国家。','The report criticized the rendition / of the suspect / to another country without a hearing.','rendition.s3 指把嫌疑人移交到另一国家接受审讯，常用于秘密引渡语境。','嫌疑人被跨境移交且没有公开听证。')],M('The report used rendition to mean a singer’s performance, although it described a suspect secretly transferred to another country.','The report used rendition for the suspect’s transfer to another country for questioning.','语境描述跨境移交嫌疑人，应使用 rendition 的引渡移交义。','meaning'),[q('What characterized the singer’s rendition?','a soft piano introduction and faster final chorus','a translation preserving the poem’s line breaks','a transfer of a suspect across a border','演唱以柔和前奏和较快的末段副歌为特点。',1,'context'),q('Why did the editor choose that rendition of the poem?','it preserved the image and line breaks','it transferred a suspect to another country','it changed every image and removed all line breaks','译本保留了意象和原诗分行。',2,'context'),q('What did the report criticize?','the suspect’s transfer without a public hearing','the singer’s faster final chorus','the editor’s choice of poem','报告批评了未经公开听证的跨境移交。',3,'context'),q('Which sense is used in “a rendition of the song”?','an artistic performance','a translated text','a suspect’s transfer','a rendition of the song 指歌曲演绎。',1,'meaning')]);
P('renew','Renew comes through Old French renouveler, “make new again”; it can extend a term, replace something old, or resume an activity after a pause.',[C('renew.s1','续期；延长有效期','The museum renewed its insurance policy for another year before the current agreement expired.','当前保险协议到期前，博物馆把保单续期了一年。','The museum renewed its policy / for another year / before it expired.','renew.s1 指安排文件、会员或协议继续有效一段时间。','博物馆在到期前延长了保单期限。'),C('renew.s2','更新；更换旧的','The technician renewed the worn brake pads before returning the delivery van to service.','技师在送货车重新投入使用前更换了磨损的刹车片。','The technician renewed the brake pads / before returning / the van to service.','renew.s2 指用同类新物替换旧物。','磨损的刹车片被换新。'),C('renew.s3','恢复；重新开始','After lunch, the negotiators renewed their discussion of the water-sharing agreement.','午餐后，谈判人员重新开始讨论水资源共享协议。','The negotiators renewed their discussion / after lunch / about water sharing.','renew.s3 指暂停后重新开始某项活动或情感。','谈判人员午餐后继续会谈。')],M('The museum renewed its insurance by letting the policy expire and making no new agreement.','The museum renewed its insurance by extending the policy before it expired.','续期是让有效期继续延长，而不是任由协议到期。','meaning'),[q('What did the museum renew for another year?','its insurance policy','the delivery van’s brake pads','the negotiators’ lunch','博物馆把保险保单续了一年。',1,'context'),q('What did the technician replace?','worn brake pads','an expired insurance policy','the water-sharing agreement','技师更换了磨损的刹车片。',2,'context'),q('What did negotiators resume after lunch?','discussion of the water-sharing agreement','the museum’s insurance payment','work on the delivery van','谈判人员午餐后重新讨论水资源协议。',3,'context'),q('Which meaning is used in “renew a passport”?','extend its validity for another period','replace an old part with a new one','resume a conversation','renew a passport 指延长护照有效期。',1,'meaning')]);
P('renewable','Renewable is formed from renew and -able; it can describe a natural energy source replenished by nature or an agreement whose term can be extended.',[C('renewable.s1','可再生的（能源）','The village installed renewable solar power that can be replenished by sunlight rather than burned as fuel.','村庄安装了可再生太阳能系统，依靠阳光补充，而不是燃烧燃料。','The village installed renewable solar power / replenished by sunlight / rather than burned.','renewable.s1 指能够由自然过程补充、不易被耗尽的资源。','太阳能会由阳光持续补充。'),C('renewable.s2','可续期的；可延期的','Her renewable one-year lease allows her to extend the rental period if both parties agree.','她的一年期租约可以续期，只要双方同意就能延长租用时间。','Her renewable lease allows an extension / if both parties / agree.','renewable.s2 指有效期限届满后可延长的合同或许可。','租约可在双方同意时续期。')],M('The lease was renewable, so the tenant had to leave when its term ended and no extension was allowed.','The lease was renewable, so the tenant could extend it if both parties agreed.','renewable 表示允许续期，而不是禁止延长有效期。','meaning'),[q('What replenishes the village’s solar power source?','sunlight','burned fuel','a rental payment','太阳能由阳光补充。',1,'context'),q('How can the tenant extend the lease?','both parties must agree','the tenant must replace solar panels','the lease must be canceled first','双方同意后租约可以延长。',2,'context'),q('Which source is renewable?','sunlight used to generate electricity','a finite supply of coal burned once','a one-time payment already spent','阳光是可再生能源。',1,'meaning'),q('Which renewable meaning applies to a one-year lease?','its term can be extended','nature replenishes it','it is made from solar energy','租约的 renewable 表示期限可以续期。',2,'meaning')]);
P('renewal','Renewal is formed from renew and -al; it means extending a contract’s validity or restoring activity and strength.',[C('renewal.s1','续期；更新','The library sent a renewal notice two weeks before each member’s annual card expired.','每位会员的年卡到期前两周，图书馆都会寄出续期通知。','The library sent a renewal notice / before each card / expired.','renewal.s1 指延长会员、合同或证件的有效期。','图书馆提醒会员续期。'),C('renewal.s2','复兴；恢复活力','The restoration of the theater brought a renewal of interest in live drama throughout the town.','剧院修复后，全镇对现场戏剧重新产生了兴趣。','The theater restoration brought a renewal of interest / in live drama / across town.','renewal.s2 指活力、兴趣或活动重新恢复。','剧院修复让当地戏剧活动复兴。')],M('The library called the card’s expiration a renewal even though the membership ended and no new term began.','The library called the extension of the card’s validity a renewal.','续期是延长有效期，会员结束且没有新期限不构成 renewal。','meaning'),[q('When did the library send the renewal notice?','two weeks before the card expired','two weeks after the membership ended','only after the theater reopened','图书馆在年卡到期前两周发出续期通知。',1,'context'),q('What did the theater’s restoration renew?','interest in live drama','the library card’s expiration date','the solar panels','剧院修复使人们重新对现场戏剧感兴趣。',2,'context'),q('What does renewal mean for a membership card?','extending its validity','removing it from a wallet','replacing the entire library','renewal 可指延长会员卡有效期。',1,'meaning'),q('Which meaning is used in “a renewal of public interest”?','a return of activity or enthusiasm','extension of a passport’s date','a natural energy source','public interest 的 renewal 指公众兴趣复苏。',2,'meaning')]);
P('renewed','Renewed is the past participle of renew; as an adjective it describes something happening again or given new energy and strength.',C('renewed.s1','重新出现的；恢复活力的','After the successful trial, the research team returned with renewed confidence and began a larger study.','试验成功后，研究团队重拾信心，开始了规模更大的研究。','The team returned with renewed confidence / after the successful trial.','renewed.s1 描述再次出现或恢复活力、力量的状态。','成功试验让团队恢复信心。'),M('The team showed renewed confidence by losing all confidence and abandoning the study after the trial.','The team showed renewed confidence by beginning a larger study after the successful trial.','renewed confidence 表示信心恢复或增强，不是信心消失。','meaning'),[q('What did the team begin after the trial?','a larger study','a renewal notice for library cards','a new rental agreement','研究团队在试验后开始更大规模的研究。'),q('What did the team regain?','confidence','its old brake pads','the theater’s stage','团队重拾了信心。',1,'context'),q('What does renewed mean in “renewed interest”?','interest that has returned or grown stronger','interest that has permanently ended','interest in renting a house','renewed interest 指重新产生或增强的兴趣。',1,'meaning'),q('Which phrase is natural?','renewed energy after a rest','renewed absence of all activity','renewed expiration with no extension','休息后恢复精力可说 renewed energy。',1,'collocation')]);
P('rennin','Rennin, also called chymosin, is the name of a milk-coagulating enzyme; the term entered scientific English through German rennin.',C('rennin.s1','凝乳酶','The cheesemaker added rennin to warm milk so its proteins would coagulate into curds.','奶酪工匠把凝乳酶加入温牛奶，使其中的蛋白质凝结成凝乳。','The cheesemaker added rennin / to warm milk / so its proteins coagulated.','rennin.s1 指使乳蛋白凝结的酶，也称 chymosin。','凝乳酶使牛奶形成凝乳。'),M('The cheesemaker added rennin to the milk to keep its proteins permanently liquid and prevent curds from forming.','The cheesemaker added rennin so the milk proteins would coagulate into curds.','rennin 的作用是促进乳蛋白凝结，而不是阻止凝乳形成。','meaning'),[q('What did the cheesemaker add to the warm milk?','rennin','a library renewal notice','a solar panel','奶酪工匠向温牛奶中加入凝乳酶。'),q('What happened to the milk proteins?','they coagulated into curds','they remained permanently liquid','they became renewable energy','牛奶蛋白质凝结成凝乳。',1,'context'),q('What is rennin also called?','chymosin','remittance','renown','rennin 也称 chymosin。',1,'meaning'),q('What kind of substance is rennin?','an enzyme','a contract','a traditional building material','rennin 是一种酶。',1,'meaning')]);
P('renounce','Renounce came through Old French from Latin renuntiare, “report or announce”; it can formally give up a right or belief, or break all ties with a person or group.',[C('renounce.s1','宣布放弃（权利/信仰）','The heir publicly renounced his claim to the estate so the dispute could be settled without a trial.','继承人公开放弃了对遗产的权利主张，使纠纷无需审判即可解决。','The heir renounced his claim / so the dispute / could be settled.','renounce.s1 指正式宣布放弃权利、头衔或信仰。','继承人放弃继承权以结束争端。'),C('renounce.s2','断绝关系；脱离','After the group demanded that she break the law, she renounced the organization and left its leadership.','该团体要求她违法后，她宣布脱离组织并辞去领导职务。','She renounced the organization / after it demanded / illegal action.','renounce.s2 可表示与某人或团体断绝联系。','她宣布脱离要求违法的组织。')],M('The heir renounced his claim by insisting he still owned the estate and demanding that the court confirm it.','The heir renounced his claim by formally giving up his right to the estate.','renounce a claim 表示正式放弃权利，不是坚持拥有该权利。','meaning'),[q('What did the heir renounce?','his claim to the estate','his leadership of the law firm','his library card','继承人放弃了对遗产的权利主张。',1,'context'),q('Why did she renounce the organization?','it demanded that she break the law','it renewed her membership card','it helped her renovate a building','她因组织要求违法而脱离它。',2,'context'),q('What does renounce mean in “renounce a title”?','formally give it up','renew it for another year','reorganize the office','renounce a title 指正式放弃头衔。',1,'meaning'),q('Which meaning is used in “renounce the group”?','break ties with it','send it a remittance','restore its building','renounce the group 指与团体断绝关系。',2,'meaning')]);
P('renovate','Renovate comes from Latin renovare, “make new again”; it means repair an old building or, more rarely, restore energy to something.',[C('renovate.s1','翻新；整修（建筑）','The owners renovated the century-old house by repairing its roof and updating the electrical wiring.','房主通过修缮屋顶、更新电线来翻新这座百年老宅。','The owners renovated the house / by repairing its roof / and updating wiring.','renovate.s1 指修复老建筑，使其恢复良好状态。','房屋经过屋顶和电路整修。'),C('renovate.s2','使恢复活力（书面，较少）','A week away from email helped renovate her energy after months of late-night work.','经过几个月的夜间工作后，暂时一周不看邮件让她恢复了精力。','A week away from email helped renovate her energy / after months / of late-night work.','renovate.s2 可较少见地指恢复活力或力量。','休息使她恢复精力。')],M('The owners renovated the house by leaving its damaged roof and unsafe wiring exactly as they were.','The owners renovated the house by repairing its roof and replacing unsafe wiring.','翻新需要修复或改善建筑状况，保留损坏屋顶和危险电线并未整修。','meaning'),[q('What work did the owners do to renovate the house?','repaired the roof and updated the wiring','let the roof keep leaking','changed only the house’s name','房主修缮屋顶并更新电线。',1,'context'),q('What helped restore her energy?','a week away from email','a new rental agreement','another month of late-night work','一周不看邮件帮助她恢复精力。',2,'context'),q('Which meaning of renovate is most common?','repair and improve an old building','give up a right or belief','send money across a border','renovate 最常见的意思是翻新建筑。',1,'meaning'),q('Which use reflects the less common figurative sense?','a quiet break renovated her energy','builders renovated the old house','workers renovated the roof tiles','休息使她恢复精力是 renovate 的较少见比喻义。',1,'context')]);
P('renovation','Renovation is formed from renovate and -ion; it means work that repairs and improves an old building, or a broader renewal of a system or tradition.',[C('renovation.s1','翻修；装修改造','The library’s renovation added accessible restrooms and repaired the leaking roof without closing the reading room.','图书馆翻修增设了无障碍洗手间，并修好了漏雨屋顶，同时没有关闭阅览室。','The renovation added accessible restrooms / and repaired the roof / while keeping the room open.','renovation.s1 指修复并改善旧建筑的工程。','翻修期间阅览室继续开放。'),C('renovation.s2','革新；复兴','The renovation of the annual festival brought back traditional music and attracted a younger audience.','年度节庆革新后重新加入传统音乐，也吸引了更年轻的观众。','The festival’s renovation brought back music / and attracted / a younger audience.','renovation.s2 可指传统或制度得到更新并重新焕发生机。','节庆更新内容后吸引了新观众。')],M('The library announced a renovation but left the leaking roof unrepaired and added no improvements to the building.','The library’s renovation repaired the roof and improved access to the building.','翻修应修复或改善建筑；什么也不改不算 renovation。','meaning'),[q('What did the library renovation add?','accessible restrooms','a new festival audience','a longer rental contract','图书馆翻修增设了无障碍洗手间。',1,'context'),q('What did the festival renovation bring back?','traditional music','the leaking roof','the old audience only','节庆革新重新加入了传统音乐。',2,'context'),q('What is a building renovation?','work to repair and improve an older building','a formal refusal to keep a title','a payment sent to a landlord','建筑 renovation 指翻修改善工程。',1,'meaning'),q('Which suffix forms renovation from renovate?','-ion','-er','-less','renovate 加 -ion 构成 renovation。',1,'word-formation')]);
P('renown','Renown came through Old French renoun from Latin nominare, “name”; it means widespread fame or a strong reputation in a field.',[C('renown.s1','声誉；名望','The surgeon achieved international renown for developing a safer procedure for treating heart disease.','这位外科医生因开发出更安全的心脏病治疗程序而享誉国际。','The surgeon achieved renown / for developing a safer procedure / for heart disease.','renown.s1 指因成就而获得的广泛名声与赞誉。','外科医生因创新治疗方法而闻名。'),C('renown.s2','在某领域的名声','The small bakery has renown among cyclists for its early opening hours and fresh bread.','这家小面包店因营业早、面包新鲜而在骑行者中享有盛名。','The bakery has renown among cyclists / for opening early / and baking fresh bread.','renown.s2 可指在特定领域或群体中的名声。','面包店在骑行者中因服务时间而知名。')],M('The surgeon’s renown was unknown to everyone, and no one had heard of the procedure or her work.','The surgeon earned renown after her procedure became widely respected.','renown 表示广泛名声；无人知晓与该词含义相反。','meaning'),[q('Why did the surgeon earn international renown?','she developed a safer heart-disease procedure','she opened a bakery early','she renewed a rental agreement','外科医生因开发更安全的治疗程序而享誉国际。',1,'context'),q('Among whom is the bakery renowned?','cyclists','the hospital’s review panel','the heirs to an estate','面包店在骑行者中享有盛名。',2,'context'),q('What does renown mean?','fame and admiration for achievement','the act of changing a name','a short-term rental payment','renown 指因成就获得的名望。',1,'meaning'),q('Which phrase is natural?','a scientist of great renown','a renown to renew the contract','renown the roof before painting','a scientist of great renown 是自然搭配。',1,'collocation')]);
P('renowned','Renowned is formed from renown and -ed; it describes someone or something widely known and admired.',C('renowned.s1','著名的；闻名的','The museum is renowned for its collection of early maps and careful conservation work.','这家博物馆以收藏早期地图和细致的文物保护工作而闻名。','The museum is renowned / for early maps / and careful conservation.','renowned 指被许多人熟知并赞赏的。','博物馆因地图藏品和保护工作享誉。'),M('The museum was renowned because nobody knew it existed and no visitors had ever heard of its map collection.','The museum was renowned because many visitors admired its map collection and conservation work.','renowned 表示广为人知、受到赞赏，不是无人知晓。','meaning'),[q('What is the museum renowned for?','early maps and careful conservation','rental apartments and renewal notices','a private meeting at the lighthouse','博物馆以早期地图和保护工作闻名。'),q('What does renowned mean?','widely known and admired','rarely mentioned and unknown','liable to be renewed each year','renowned 指广为人知并受到赞赏。',1,'meaning'),q('Which person is renowned?','a pianist whose performances are admired worldwide','a private beginner nobody has heard of','a renter who changed apartments','演出广受赞赏的钢琴家是 renowned。',1,'context'),q('Which preposition naturally follows renowned?','renowned for its map collection','renowned at its map collection','renowned by its map collection','renowned for 是自然搭配。',1,'grammar')]);
P('rent','Rent came through Old French rente from a Latin term for payment; it can be money paid for use, pay to use something, or let property to someone else.',[C('rent.s1','租金；房租','The monthly rent includes water but not electricity, so the tenants budget for both bills separately.','月租包含水费但不含电费，因此租户要分别为两项账单做预算。','The monthly rent includes water / but not electricity / so tenants budget separately.','rent.s1 指为使用房间、住房或设备而定期支付的钱。','租户按月支付租金。'),C('rent.s2','租用；租入','They rented a small van for the weekend to carry furniture to their new apartment.','他们周末租了一辆小货车，把家具搬到新公寓。','They rented a van / for the weekend / to move furniture.','rent.s2 作动词指付费借用别人的物品或房屋。','他们付费租用货车搬家。'),C('rent.s3','出租','The owner rents two rooms to students during the university term.','大学学期期间，房主把两间房出租给学生。','The owner rents two rooms / to students / during term time.','rent.s3 作动词指收取费用让别人使用自己的房屋或物品。','房主把房间出租给学生。')],M('The landlord rented the room to the student by paying the student every month to live there.','The landlord rented the room to the student in return for monthly rent.','出租方收取租金；每月付钱给租客的方向相反。','meaning'),[q('What does the monthly rent include?','water but not electricity','electricity but not water','the tenant’s furniture','月租包含水费但不含电费。',1,'context'),q('Why did the couple rent a van?','to move furniture to their new apartment','to receive their monthly room rent','to renew a library card','他们租货车搬运家具。',2,'context'),q('Who rents rooms to students in the final example?','the owner','the student','the university librarian','房主把两间房出租给学生。',3,'context'),q('Which meaning is used in “pay rent”?','money paid regularly for use of a place','the act of letting a room to someone','the act of hiring a vehicle','pay rent 指支付房租。',1,'meaning')]);
P('rentable','Rentable is formed from rent and -able; it describes property or equipment that its owner can let to another person for payment.',C('rentable.s1','可供出租的','The renovated basement is now rentable because it has a separate entrance and meets the fire-safety code.','翻修后的地下室现在可以出租，因为它有独立入口并符合消防规范。','The basement is rentable / because it has a separate entrance / and meets safety rules.','rentable 指具备条件、可以出租给他人使用的房屋或物品。','独立入口和合规设施使地下室可出租。'),M('The basement was rentable despite having no legal exit and failing every required fire-safety check.','The basement became rentable after a separate exit was installed and safety rules were met.','不符合安全要求的空间通常不能合法出租。','meaning'),[q('What made the basement rentable?','a separate entrance and compliance with fire-safety rules','the lack of an exit and failed inspections','the owner’s decision to rename it','独立入口和消防合规使地下室可出租。'),q('What does rentable mean?','available or suitable to be rented out','already paid for by a renter','impossible to let to anyone','rentable 表示可以出租或适合出租。',1,'meaning'),q('Which item is rentable?','a working van offered to customers for a fee','a broken appliance that cannot be used','a private letter with no owner permission','可供顾客付费使用的车辆可以出租。',1,'context'),q('Which suffix gives rentable the sense “able to be”?','-able','-ed','-ness','-able 表示“可以、能够”。',1,'word-formation')]);
P('rental','Rental comes from rent and -al; it can mean the activity of renting, the payment charged, or an item intended to be rented out.',[C('rental.s1','租赁；出租','The rental of camera equipment requires a deposit and a signed inventory form.','租用摄影器材需要缴纳押金并签署物品清单。','The rental of camera equipment requires / a deposit / and a signed form.','rental.s1 指租用或出租的活动。','租用器材要交押金并签单。'),C('rental.s2','租金','The weekly rental for the van was lower than the cost of hiring a moving company.','这辆货车的周租金低于雇搬家公司所需的费用。','The weekly rental for the van / was lower / than hiring a moving company.','rental.s2 指为租用某物支付的费用。','货车周租金较便宜。'),C('rental.s3','出租用的','The rental car was parked outside the station and ready for the visitors to collect.','出租车停在车站外，游客可以前去取车。','The rental car was parked / outside the station / ready for collection.','rental.s3 作定语表示供出租或租用的。','游客可以在车站外取出租车。')],M('The rental car was available to customers but the company insisted it was a private vehicle that could never be hired.','The rental car was available for customers to hire from the company.','rental car 指供客户租用的车辆，不是禁止出租的私人车。','meaning'),[q('What does renting camera equipment require?','a deposit and a signed inventory','a weekly rent payment for a van','a trip to the lighthouse','租用摄影器材要交押金并签物品清单。',1,'context'),q('What was cheaper than hiring a moving company?','the van’s weekly rental','a rental agreement renewal','the camera deposit','货车的周租金更便宜。',2,'context'),q('Where was the rental car ready for collection?','outside the station','inside the refectory','at the remote farm','出租车停在车站外供人领取。',3,'context'),q('Which meaning is used in “the rental of equipment”?','the activity of hiring it','the weekly fee only','an item available to hire','rental of equipment 指租用行为。',1,'meaning')]);
P('rental agreement','Rental agreement is a compound phrase naming a written contract that allows someone to use a house, vehicle or machine for a fixed period in return for payments.',C('rental agreement.s1','租约；租赁协议','The rental agreement states that the tenant must report water leaks within twenty-four hours and pay rent on the first day of each month.','租赁协议规定租户须在二十四小时内报告漏水，并在每月一日交租。','The rental agreement states / how soon to report leaks / and when rent is due.','rental agreement.s1 指规定租赁期限、付款和双方责任的书面合同。','协议写明报漏水和交租日期。'),M('The rental agreement set no term, payment amount or responsibilities and existed only as an unsigned rumor.','The rental agreement recorded the rental term, payment schedule and duties of both parties.','租赁协议应记录期限、付款和责任，不能只是没有具体内容的传闻。','meaning'),[q('When must the tenant report a water leak?','within twenty-four hours','after the lease ends','only when rent is renewed','协议要求在二十四小时内报告漏水。'),q('On which day is monthly rent due?','the first day','the last day of the year','whenever the landlord renames the property','租金每月一日到期。',1,'context'),q('What is a rental agreement?','a written contract for using property for a set period','a receipt for a returned book','a note reminding someone to pay','rental agreement 是固定期限的书面租赁合同。',1,'meaning'),q('What does the agreement commonly specify?','term, payment schedule and responsibilities','the renter’s childhood memories','the building’s remote location only','租赁协议通常写明期限、付款方式和责任。',1,'context')]);
P('renter','Renter is formed from rent and -er; it names someone who pays to use a home, room, vehicle or other property.',C('renter.s1','承租人；租房者','The renter notified the landlord about the broken heater and included a photograph in the repair request.','租户通知房东暖气损坏，并在维修申请中附上照片。','The renter notified the landlord / about the broken heater / with a photograph.','renter.s1 指支付租金以使用住房、房间或车辆的人。','租户向房东报告了暖气故障。'),M('The renter collected monthly payments from the tenant for the apartment, although the renter was the person paying to live there.','The renter paid the landlord monthly to use the apartment.','租户支付租金；收取租金的一方通常是房东。','meaning'),[q('What problem did the renter report?','a broken heater','a missing concert rendition','a remote solar panel','租户报告了暖气故障。'),q('To whom did the renter send the repair request?','the landlord','the library’s renewal office','the theater audience','租户把维修申请发给房东。',1,'context'),q('Who is a renter?','someone who pays to use a place or object','someone who owns every property they use','someone who renews another person’s contract','renter 指付费租用住房或物品的人。',1,'meaning'),q('Which suffix names the person who rents?','-er','-al','-ment','rent 加 -er 构成 renter。',1,'word-formation')]);
P('renunciation','Renunciation is formed from renounce and -ation; it means a deliberate formal refusal to keep a title, possession or desire.',C('renunciation.s1','宣布放弃','The prince’s renunciation of the title was recorded in a signed statement delivered to the parliament.','王子放弃头衔的决定被记录在一份递交给议会的签字声明中。','The renunciation of the title / was recorded / in a signed statement.','renunciation 指有意正式放弃某项头衔、权利、财产或欲望。','放弃头衔以书面声明记录。'),M('The prince’s renunciation of the title meant he kept the title and demanded that everyone continue using it.','The prince’s renunciation of the title meant he formally gave it up.','renunciation 表示正式放弃，与保留并要求继续使用头衔相反。','meaning'),[q('What did the prince renounce?','his title','the parliament’s rental agreement','his remote residence','王子正式放弃了头衔。'),q('How was the renunciation recorded?','in a signed statement delivered to parliament','in an unsigned reminder on a phone','in a theater performance','放弃决定记在递交议会的签字声明中。',1,'context'),q('What does renunciation mean?','a deliberate formal refusal to keep something','a renewal of a contract','a payment for work','renunciation 指有意正式放弃某物。',1,'meaning'),q('Which verb is renunciation based on?','renounce','renovate','reopen','renunciation 由 renounce 加 -ation 构成。',1,'word-formation')]);
P('reoccupy','Reoccupy combines re- and occupy; it means take control of or move into a place again after having left it.',C('reoccupy.s1','重新占领；重新进驻','The conservation team reoccupied the field station after inspectors confirmed that the roof was safe.','检查员确认屋顶安全后，保护团队重新进驻了野外站点。','The team reoccupied the station / after inspectors confirmed / its roof was safe.','reoccupy 指离开后重新进入或控制一个地点。','团队在检查合格后返回站点。'),M('The team reoccupied the station by staying miles away and never entering or taking control of it again.','The team reoccupied the station by returning after the safety inspection.','重新进驻要求再次进入地点，不是一直待在远处。','meaning'),[q('When did the team reoccupy the field station?','after inspectors confirmed the roof was safe','before inspectors arrived and the roof was checked','after the station had been demolished','屋顶通过检查后团队重新进驻。'),q('What did inspectors confirm?','the roof was safe','the station had been renamed','the rental agreement had expired','检查员确认了屋顶安全。',1,'context'),q('What does reoccupy mean?','move into or take control of a place again','renovate a place for the first time','leave a place permanently','reoccupy 指再次进入或占据一个地点。',1,'meaning'),q('Which prefix gives reoccupy the sense “again”?','re-','un-','mis-','re- 表示重新进驻。',1,'word-formation')]);
P('reopen','Reopen combines re- and open; it means make a place or service accessible again or return a discussion to consideration.',C('reopen.s1','重开；重新开放','The clinic will reopen on Monday after workers complete repairs to the damaged entrance.','工人修好受损入口后，诊所将于周一重新开放。','The clinic will reopen / on Monday / after entrance repairs are finished.','reopen 指关闭后再次开放，也可指重新开始讨论某事。','入口维修完成后诊所再次营业。'),M('The clinic reopened on Monday by remaining closed to all patients and refusing to offer appointments.','The clinic reopened on Monday after repairs, allowing patients to return.','reopen 表示再次开放营业，不是继续关闭。','meaning'),[q('When will the clinic reopen?','on Monday','after a year of permanent closure','before workers repair the entrance','诊所将在周一重新开放。'),q('What must workers finish first?','repairs to the damaged entrance','the theater’s renovation','the library’s renewal notices','工人要先修好受损入口。',1,'context'),q('What does reopen mean?','make accessible or operational again','close a place permanently','change the name of a building','reopen 指再次开放或恢复运营。',1,'meaning'),q('Which phrase uses reopen figuratively?','reopen debate on the proposed rule','reopen the clinic after repairs','reopen the station doors at dawn','reopen debate 指重新开始讨论。',1,'context')]);
P('reorganization','Reorganization is formed from reorganize and -ation; it means arranging a company, group or system again in a different structure.',C('reorganization.s1','重组；重新组织','The reorganization merged two support teams and created a single desk for customer requests.','重组把两个支持团队合并，并设立了统一的客户请求服务台。','The reorganization merged two teams / and created / one customer-service desk.','reorganization 指以不同方式重新安排组织或工作结构。','团队合并后形成统一服务台。'),M('The company called it a reorganization while keeping every team, reporting line and responsibility exactly unchanged.','The company reorganized by merging teams and changing their reporting structure.','组织结构完全没有变化就不能称为 reorganization。','meaning'),[q('What did the reorganization merge?','two support teams','two rental agreements','two remote villages','重组把两个支持团队合并。'),q('What new service point did it create?','a single desk for customer requests','a separate desk for each old team','a renewal notice for every client','重组后设立了统一客户服务台。',1,'context'),q('What is a reorganization?','a new arrangement of a group or system','a payment for consulting work','a renewed performance of a song','reorganization 指重新安排组织结构。',1,'meaning'),q('Which suffix forms reorganization as a noun?','-ation','-able','-ish','reorganize 加 -ation 构成 reorganization。',1,'word-formation')]);
P('reorganize','Reorganize combines re- and organize; it means arrange people, work or objects again in a different or more effective order.',C('reorganize.s1','重组；重新安排','The shop reorganized its shelves so customers could find gluten-free foods in one clearly marked aisle.','商店重新整理了货架，让顾客能在一个标识清楚的过道找到无麸质食品。','The shop reorganized its shelves / so customers could find / gluten-free foods together.','reorganize 指以新的顺序或结构重新安排。','货架重排后商品更容易查找。'),M('The shop reorganized its shelves by leaving every item in its old place and adding no labels or new arrangement.','The shop reorganized its shelves by grouping gluten-free products in one marked aisle.','重新整理需要改变排列方式；维持原样不算 reorganize。','meaning'),[q('What products did the shop group together?','gluten-free foods','rental cars','Renaissance books only','商店把无麸质食品放在一起。'),q('Why did the shop reorganize the shelves?','to help customers find products more easily','to hide every product label','to make the shop permanently inaccessible','重排货架是为了让顾客更容易找到商品。',1,'context'),q('What does reorganize mean?','arrange something again in a different order','renounce a title formally','recover after an illness','reorganize 指重新安排。',1,'meaning'),q('Which phrase is natural?','reorganize the work schedule','reorganize the rent payment into a renter','reorganize a person of renown','reorganize the work schedule 是自然搭配。',1,'collocation')]);
P('reorient','Reorient combines re- and orient; it means help someone adjust to a new situation or change the direction or goal of a plan.',[C('reorient.s1','使重新适应','The counselor helped the new students reorient themselves after they transferred to a much larger school.','转入一所大得多的学校后，辅导员帮助新生重新适应环境。','The counselor helped the students reorient themselves / after transferring / to the larger school.','reorient.s1 指帮助人适应新环境或新情况。','辅导员帮助转学生适应新学校。'),C('reorient.s2','调整方向；重新确定目标','After customer surveys changed, the company reoriented its research toward lower-cost medical devices.','客户调查结果变化后，公司把研发方向转向了成本更低的医疗设备。','The company reoriented its research / toward lower-cost devices / after new survey results.','reorient.s2 指改变行动方向或目标。','新调查促使公司调整研发目标。')],M('The company reoriented its research by keeping the same target and refusing to change its direction after new surveys.','The company reoriented its research toward lower-cost devices after reviewing the new surveys.','reorient 的目标义要求改变方向，而不是完全维持原目标。','meaning'),[q('Who helped the transfer students adjust?','the counselor','the medical-device supplier','the school’s repeater','辅导员帮助新生适应新学校。',1,'context'),q('What new research direction did the company choose?','lower-cost medical devices','larger and more expensive devices','the same target with no change','公司把研发方向转向较低成本的医疗设备。',2,'context'),q('What does reorient mean of a person?','help them adjust to a new situation','make them repeat a course','send them back to their home country','reorient someone 指帮助其重新适应环境。',1,'meaning'),q('What does reorient mean of a plan?','change its direction or goal','repeat it exactly without changes','repeal it by law','reorient a plan 指调整方向或目标。',2,'meaning')]);
P('repack','Repack combines re- and pack; it means put items into packages again, sometimes changing the package size or brand.',C('repack.s1','再打包','The warehouse had to repack the tea into smaller boxes after the retailer changed its shelf-size requirements.','零售商改变货架尺寸要求后，仓库只好把茶叶重新装进较小的盒子。','The warehouse repacked the tea / into smaller boxes / after the retailer changed its requirements.','repack 指再次把物品装入包装中，也可更换包装规格。','茶叶按新的货架要求换用小盒包装。'),M('The warehouse repacked the tea by removing it from the boxes and leaving every bag loose on the floor.','The warehouse repacked the tea into smaller boxes for the retailer’s shelves.','重新打包是再次装入包装，不是把商品散放在地上。','meaning'),[q('Why did the warehouse repack the tea?','the retailer changed shelf-size requirements','the tea had been renamed','the retailer canceled every order','零售商更改货架尺寸后需要重新包装。'),q('What size boxes did the warehouse use?','smaller boxes','larger boxes only','no boxes at all','茶叶重新装进较小的盒子。',1,'context'),q('What does repack mean?','put items into packages again','paint a package again','reorganize the retailer’s staff','repack 指重新包装物品。',1,'meaning'),q('What does re- mean in repack?','again','before','away from','re- 表示再次包装。',1,'word-formation')]);
P('repaint','Repaint combines re- and paint; it means cover a wall, door or canvas with paint once more.',C('repaint.s1','再漆；重绘','The tenants agreed to repaint the hallway after moving furniture had scratched the pale green walls.','搬家具时刮花了浅绿色墙面，租户同意重新粉刷走廊。','The tenants agreed to repaint the hallway / after furniture / scratched the walls.','repaint 指再次用颜料覆盖墙壁、门或画布。','墙面被刮花后重新粉刷。'),M('The tenants repainted the hallway by leaving the scratched green walls untouched and adding no new paint.','The tenants repainted the hallway to cover the scratches with a fresh coat.','重新粉刷需要加上新漆，保持刮痕不变不算 repaint。','meaning'),[q('What damaged the hallway walls?','moving furniture','smaller tea boxes','a medical-device survey','搬家具时刮花了走廊墙面。'),q('What did the tenants decide to repaint?','the hallway','the furniture’s rental agreement','the tea boxes','租户决定重新粉刷走廊。',1,'context'),q('What does repaint mean?','apply paint again','remove paint without replacing it','change the direction of a plan','repaint 指再次涂漆。',1,'meaning'),q('Which surface can someone repaint?','a scratched door','a spoken conversation','a student’s course schedule','被刮花的门可以重新粉刷。',1,'context')]);
P('repair','Repair came through Old French reparer from Latin reparare, “make ready again”; it can mean fix damage, the work of fixing, or make amends in a relationship or reputation.',[C('repair.s1','修理；修补','A technician repaired the broken lift before the apartment building reopened to residents.','公寓楼重新向居民开放前，技师修好了损坏的电梯。','A technician repaired the lift / before the building / reopened to residents.','repair.s1 作动词指修好损坏的物品或设施。','电梯修好后大楼重新开放。'),C('repair.s2','修理工作；维修','The repair of the roof took three days because workers had to replace several water-damaged beams.','屋顶维修花了三天，因为工人需要更换几根被水损坏的梁。','The roof repair took three days / because several beams / needed replacing.','repair.s2 作名词指修理的过程或结果。','屋顶维修需要更换受损梁。'),C('repair.s3','补救；挽回','The manager apologized publicly in an effort to repair the company’s reputation after the faulty product recall.','产品召回后，经理公开道歉，试图挽回公司的声誉。','The manager apologized / in an effort to repair / the company’s reputation.','repair.s3 可指修复关系、声誉或损失。','经理通过道歉试图挽回声誉。')],M('The technician repaired the lift by leaving its broken motor in place and refusing to restore its operation.','The technician repaired the lift by replacing the broken motor and testing it before reopening.','维修需要修复故障并恢复运行，而不是保留坏电机。','meaning'),[q('What did the technician repair?','the broken lift','the company’s public image','the roof beams','技师修好了损坏的电梯。',1,'context'),q('Why did the roof repair take three days?','workers replaced water-damaged beams','the lift motor was removed','the company issued a product recall','屋顶维修需要更换受水损坏的梁。',2,'context'),q('What did the manager try to repair?','the company’s reputation','the apartment lift','the roof beams','经理试图挽回公司的声誉。',3,'context'),q('Which meaning is used in “the repair took three days”?','the work of fixing something','fixing a relationship','making a building reopen','the repair 指维修工作。',2,'meaning')]);
P('repatriate','Repatriate comes from Latin repatriare, “return to one’s country”; it means return a refugee, prisoner or funds to the country of origin.',C('repatriate.s1','遣返回国','The agency arranged to repatriate the stranded citizens after flights resumed between the two countries.','两国间恢复航班后，机构安排把滞留公民送回祖国。','The agency arranged to repatriate the citizens / after flights resumed / between the countries.','repatriate 指把人或资金送回原属国家。','航班恢复后滞留公民得以回国。'),M('The agency repatriated the stranded citizens by sending them permanently to a third country rather than their home country.','The agency repatriated the citizens by arranging their return to their home country.','repatriate 表示送回原属国家，不是永久送往第三国。','meaning'),[q('What allowed the agency to arrange the citizens’ return?','flights resumed between the countries','the citizens signed a rental agreement','the agency repainted the airport','两国间恢复航班后，机构安排公民回国。',1,'context'),q('Where were the citizens repatriated to?','their country of origin','a permanent third country','the agency’s remote office','他们被送回了原属国家。',1,'meaning'),q('Which action is repatriation?','returning a displaced person to their home country','moving a renter to another apartment','repainting a national border','把流离失所者送回祖国属于 repatriate。',1,'context'),q('What does the Latin source repatriare mean?','return to one’s country','repair a building','pay money back','repatriate 源自拉丁语，意为“回到自己的国家”。',1,'word-formation')]);
P('repay','Repay combines re- and pay; it means give back borrowed money, return a kindness, or be worth the effort or cost.',[C('repay.s1','偿还；还钱','He repaid the loan in six monthly installments and kept the final receipt for his records.','他分六个月偿还贷款，并把最后一张收据留作记录。','He repaid the loan / in six monthly installments / and kept the receipt.','repay.s1 指把借来的钱还给出借人。','借款分六期偿还。'),C('repay.s2','报答；回报','She repaid her neighbor’s kindness by caring for the garden while he recovered from surgery.','邻居手术康复期间，她帮忙照看花园，以报答对方的好意。','She repaid his kindness / by caring for the garden / during his recovery.','repay.s2 指以善意或行动回报别人的帮助。','她以照料花园回报邻居。'),C('repay.s3','值得（付出）','The long hike repaid their effort when they reached the lake and watched the sunrise over the mountains.','他们到达湖边、看到山间日出时，觉得长途徒步的付出得到了回报。','The hike repaid their effort / when they reached the lake / at sunrise.','repay.s3 常指结果好到足以补偿付出的时间或努力。','壮丽日出让徒步付出显得值得。')],M('He repaid the loan by borrowing the same amount again and keeping every installment unpaid.','He repaid the loan by returning the borrowed money in monthly installments.','repay loan 表示归还借款，重新借钱并拖欠不算偿还。','meaning'),[q('How did he repay the loan?','in six monthly installments','by caring for his neighbor’s garden','by hiking to the lake','他分六个月偿还贷款。',1,'context'),q('How did she repay her neighbor’s kindness?','by caring for his garden','by lending him money he never returned','by canceling his surgery','她照看邻居的花园以报答好意。',2,'context'),q('What repaid the hikers’ effort?','the sunrise over the lake','the final loan receipt','a new rental agreement','山间日出让徒步的辛苦变得值得。',3,'context'),q('Which meaning is used in “The view repaid the climb”?','was worth the effort','returned borrowed money','repaid a kindness','The view repaid the climb 指景色值得攀登付出。',3,'meaning')]);
P('repayment','Repayment is formed from repay and -ment; it means the act of paying borrowed money back or the money paid back.',C('repayment.s1','偿还；偿还款项','The lender lowered the monthly repayment after the borrower provided proof of reduced income.','借款人提供收入减少的证明后，贷款方降低了每月还款额。','The lender lowered the monthly repayment / after reviewing / the income evidence.','repayment 指偿还借款的行为或实际偿还的款项。','贷款方调整了每月应还金额。'),M('The lender called the unpaid balance a repayment even though the borrower had returned no money.','The lender called the monthly amount paid back toward the loan a repayment.','repayment 是已偿还或正在偿还的款项，不是尚未支付的余额。','meaning'),[q('What evidence did the borrower provide?','proof of reduced income','a receipt for repainted walls','a reference to a remote village','借款人提供了收入减少的证明。'),q('What did the lender lower?','the monthly repayment','the original loan amount already borrowed','the garden’s renovation','贷款方降低了每月还款额。',1,'context'),q('What does repayment mean?','money paid back or the act of paying it back','a reward for helping a neighbor','an official cancellation of a law','repayment 指偿还行为或偿还款项。',1,'meaning'),q('Which word is repayment formed from?','repay','repatriate','repaint','repayment 由 repay 加 -ment 构成。',1,'word-formation')]);
P('repeal','Repeal came through Anglo-French repealer, “call back”; it means officially cancel a law, rule or formal decision.',C('repeal.s1','废除；撤销','Parliament voted to repeal the outdated tax rule after an independent review found it unfair to small farms.','独立审查发现旧税收规定对小农场不公平后，议会投票废除了该规定。','Parliament voted to repeal the tax rule / after a review / found it unfair.','repeal 指以正式程序取消法律、规章或决定。','议会正式废除了不公平的旧规定。'),M('Parliament repealed the tax rule by keeping it fully in force and rejecting every proposal to cancel it.','Parliament repealed the tax rule by voting to cancel it.','repeal 表示正式废除，继续维持法律有效与其相反。','meaning'),[q('Why did Parliament vote to repeal the tax rule?','a review found it unfair to small farms','it had just been introduced and worked well','the farms had renewed their leases','审查发现旧规定对小农场不公平。',1,'context'),q('What does repeal mean?','officially cancel a law or rule','repeat it aloud','repair damage to a reputation','repeal 指正式废除法律或规定。',1,'meaning'),q('Which action is a repeal?','a legislature cancels an outdated regulation','a clerk renews a permit for another year','a committee reorganizes its offices','立法机构取消过时法规属于 repeal。',1,'context'),q('What kind of object is commonly repealed?','a law or formal rule','a broken kitchen appliance','a private kindness','法律或正式规定可以被 repeal。',1,'collocation')]);
P('repeat','Repeat comes from Latin repetere, “seek again”; it can say or do something again, happen again, or mean a replay or recurring event.',[C('repeat.s1','重复说；重做','The teacher asked the student to repeat the final instruction because the room had been noisy.','教室里很吵，老师请学生把最后一条指示再说一遍。','The teacher asked the student to repeat / the final instruction / because of the noise.','repeat.s1 指再次说、写或做某事。','老师请学生再说一次指示。'),C('repeat.s2','再次发生','The same payment error could repeat unless the software team corrected the billing rule.','除非软件团队修正计费规则，否则同样的付款错误可能再次发生。','The payment error could repeat / unless the billing rule / was corrected.','repeat.s2 指以相同方式再次发生。','修正规则可避免付款错误再次出现。'),C('repeat.s3','重播；重复的事物','The station scheduled a repeat of the documentary so viewers who missed the first showing could watch it later.','电视台安排重播这部纪录片，让错过首播的观众之后能观看。','The station scheduled a repeat / for viewers / who missed the first showing.','repeat.s3 可指电视节目重播或再次举行的活动。','纪录片安排了再次播出。')],M('The student repeated the instruction by changing every key detail and giving the class a different rule.','The student repeated the instruction by saying the same rule again.','repeat 指再次说相同内容，不是换成另一条指示。','meaning'),[q('Why did the teacher ask the student to repeat the instruction?','the room had been noisy','the payment error had returned','viewers missed a documentary','教室吵闹使老师没听清指示。',1,'context'),q('What could happen if the billing rule stayed unchanged?','the same payment error could happen again','the documentary would repeat on television','the teacher would repeal the rule','付款错误可能再次发生。',2,'context'),q('What did the station schedule for viewers who missed the first showing?','a repeat of the documentary','a new tax law','a rental agreement','电视台安排了纪录片重播。',3,'context'),q('Which meaning is used in “Please repeat your name”?','say it again','happen again by itself','show a program a second time','Please repeat your name 表示请再说一遍名字。',1,'meaning')]);
P('repeated','Repeated is formed from repeat and -ed; it describes something done or happening more than once.',C('repeated.s1','反复的；再三的','After repeated warnings about the icy steps, the building manager spread salt across the entrance.','多次警告楼梯结冰后，楼管在入口处撒了盐。','After repeated warnings / about icy steps / the manager spread salt.','repeated 描述发生或做过多次的事。','管理人员多次提醒后采取防滑措施。'),M('The manager described the warning as repeated although it was sent once and never mentioned again.','The manager described the warnings as repeated because they were sent several times.','只发出一次并未再次提及的警告不是 repeated。','meaning'),[q('What hazard did the repeated warnings mention?','icy steps','a broken solar panel','a rent repayment','多次警告都提到楼梯结冰。'),q('What did the building manager do?','spread salt across the entrance','repeatedly repaint the theater','repealed the warnings','楼管在入口处撒了盐。',1,'context'),q('What does repeated mean?','done or happening more than once','completed exactly once','canceled by a legislature','repeated 指多次发生或进行。',1,'meaning'),q('Which phrase is natural?','repeated attempts to restart the engine','repeated once and never again','a repeated repayment that was never paid','repeated attempts 表示反复尝试。',1,'collocation')]);
P('repeatedly','Repeatedly is formed from repeated and -ly; it means again and again or many times.',C('repeatedly.s1','反复地；再三地','The smoke alarm beeped repeatedly until the caretaker replaced its low battery.','烟雾报警器反复鸣响，直到管理员更换了电量不足的电池。','The alarm beeped repeatedly / until the caretaker / replaced its battery.','repeatedly 修饰动作，表示该动作发生了许多次。','报警器连续多次鸣响。'),M('The alarm beeped repeatedly by sounding only once and remaining silent for the rest of the day.','The alarm beeped repeatedly, sounding again and again until its battery was replaced.','只响一次不符合 repeatedly 所表示的多次发生。','meaning'),[q('What did the caretaker replace?','the alarm’s low battery','the theater’s old stage','the renter’s lease','管理员更换了报警器的低电量电池。'),q('How often did the alarm beep?','again and again','once only','not at all','报警器反复鸣响。',1,'context'),q('What does repeatedly mean?','many times','for the first time','at a distance','repeatedly 指反复、多次地。',1,'meaning'),q('Which sentence uses repeatedly correctly?','The app repeatedly asked for a password until she entered it.','The app asked once and repeatedly never asked again.','The app repeatedly renewed one fixed-term lease once.','应用多次要求输入密码，符合 repeatedly。',1,'grammar')]);
P('repeater','Repeater is formed from repeat and -er; it can name someone who takes a course or commits an offense again, or a device that retransmits a signal.',[C('repeater.s1','重修者；再犯者','The course repeater joined the new class after failing the certification exam the previous year.','这名课程重修者去年未通过认证考试后，加入了新一届课程。','The repeater joined the new class / after failing / the exam last year.','repeater.s1 可指再次修读课程或再次犯罪的人。','考试未通过后学生重修该课程。'),C('repeater.s1','中继器','A radio repeater on the hill retransmits weak signals so emergency crews can communicate across the valley.','山上的无线电中继器会转发微弱信号，使救援人员能跨山谷通信。','A radio repeater retransmits weak signals / so crews can communicate / across the valley.','repeater.s2 指接收并重新发送信号的设备。','中继器扩大了无线电通信范围。')],M('The hilltop repeater improved communication by blocking incoming radio signals and never sending them onward.','The hilltop repeater improved communication by receiving and retransmitting radio signals.','中继器通过转发信号扩大通信范围，不是阻断信号。','meaning'),[q('Why did the student join a new class?','he had failed the certification exam','he had already passed and graduated','the class needed a rental agreement','学生未通过认证考试，所以重修课程。',1,'context'),q('What did the hilltop repeater retransmit?','weak radio signals','the course’s tuition payments','a warning about the theater roof','中继器转发微弱无线电信号。',1,'context'),q('What is a repeater in communications?','a device that retransmits a signal','a person who renews a license','a device that repaints a wall','无线电 repeater 是转发信号的设备。',1,'meaning'),q('Which meaning is used in “a course repeater”?','a person taking the course again','a device rebroadcasting a signal','a person who repeals a law','course repeater 指重修课程的人。',1,'meaning')]);
P('repel','Repel comes from Latin repellere, “drive back”; it can force an attack away, cause strong dislike, or keep a liquid from sticking or soaking in.',[C('repel.s1','击退；驱走','The guards used bright lights to repel birds from the airport runway during night flights.','夜间航班期间，守卫用强光驱赶机场跑道上的鸟。','The guards used bright lights / to repel birds / from the runway.','repel.s1 指迫使攻击者或不受欢迎的事物离开。','强光把鸟从跑道上驱走。'),C('repel.s2','使厌恶；使反感','The spoiled milk’s sour odor repelled the campers, so they sealed it in a bag and carried it away.','变质牛奶的酸臭味令露营者反感，他们把它封进袋子带走。','The sour odor repelled the campers / so they sealed the milk / in a bag.','repel.s2 指使人产生强烈厌恶或反感。','酸臭气味让露营者不愿接近。'),C('repel.s3','排斥；防水','The wax coating repels water and keeps the canvas from soaking through in light rain.','蜡质涂层可以防水，使帆布在小雨中不会被浸透。','The wax coating repels water / and keeps the canvas / from soaking through.','repel.s3 指阻止某物附着或渗入，常用于防水表面。','涂层使水珠无法浸入帆布。')],M('The wax coating repelled water by absorbing it quickly and soaking the canvas through.','The wax coating repelled water by making droplets bead on the canvas surface.','防水涂层阻止水渗入，而不是让帆布迅速吸水。','meaning'),[q('What did the guards use to repel birds?','bright lights','a wax coating','a rental car','守卫用强光驱赶跑道上的鸟。',1,'context'),q('What repelled the campers?','the sour odor of spoiled milk','the airport’s runway lights','a radio signal from a repeater','变质牛奶的酸臭味使露营者反感。',2,'context'),q('How did the wax coating repel water?','it kept water from soaking into the canvas','it absorbed water into every fiber','it attracted water to the fabric','蜡层阻止水渗入帆布。',3,'context'),q('Which meaning is used in “the odor repelled her”?','made her feel strong dislike','forced an attacker away','kept water from soaking in','odor repelled her 指气味令她厌恶。',2,'meaning')]);
P('repent','Repent came through Old French repentir from Latin paenitere, “regret”; it means sincerely regret a wrong act, often with a wish to change.',C('repent.s1','懊悔；悔改','He repented of falsifying the report and returned the money he had taken from the project account.','他为伪造报告而悔改，并退还了从项目账户中拿走的钱。','He repented of falsifying the report / and returned / the project money.','repent 指真诚懊悔错误行为，常包含改过的愿望。','他承认错误并退还款项。'),M('He repented of falsifying the report by continuing to falsify records and refusing to return the money.','He repented of falsifying the report and corrected the records.','悔改通常伴随停止错误并努力改正，而不是继续造假。','meaning'),[q('What did he repent of doing?','falsifying the report','retransmitting a radio signal','repainting a hallway','他为伪造报告而悔改。'),q('What did he return?','money taken from the project account','the repeater to the hilltop','the sour milk to the campers','他退还了从项目账户中拿走的钱。',1,'context'),q('What does repent mean?','sincerely regret a wrong act','repeat a phrase many times','force birds away from a runway','repent 指真诚懊悔做错的事。',1,'meaning'),q('Which preposition commonly follows repent?','of','at','from','repent of 是常见搭配。',1,'grammar')]);
P('repercussion','Repercussion comes from Latin repercussio, “a striking back”; it means a later effect, often an unpleasant one, that follows an event or decision.',C('repercussion.s1','深远影响；后果','The budget cut had a repercussion for rural clinics: several stopped offering evening appointments.','预算削减给乡村诊所带来后果：几家诊所停止了晚间预约服务。','The budget cut had a repercussion / for rural clinics / that lost evening appointments.','repercussion 指某事件或决定随后造成的影响，常带负面意味。','预算削减导致乡村诊所减少服务。'),M('The budget cut had no repercussions because it caused rural clinics to lose staff and cancel services.','The budget cut had serious repercussions because rural clinics lost staff and canceled services.','造成失去员工和取消服务正是削减预算带来的后果。','meaning'),[q('What did some rural clinics stop offering?','evening appointments','radio repeaters','rental renewals','一些乡村诊所停止晚间预约。',1,'context'),q('What decision caused this repercussion?','a budget cut','a hallway repainting','a course repetition','预算削减导致诊所服务变化。',1,'context'),q('What is a repercussion?','a later effect of an event or decision','a repeated performance of a song','a formal cancellation of a law','repercussion 指事件或决定后续造成的影响。',1,'meaning'),q('Why are repercussions often described as serious?','they can be later harmful consequences','they are always pleasant rewards','they happen before the decision','repercussions 常指严重或不利的后果。',1,'meaning')]);
P('repertoire','Repertoire came through French from a Latin word for an inventory; it means the works a performer can present or the range of skills a person can use.',[C('repertoire.s1','全部演出曲目；常备剧目','The orchestra’s repertoire includes new commissions as well as several familiar symphonies.','乐团的常备曲目既包括新委约作品，也包括几首熟悉的交响曲。','The orchestra’s repertoire includes / new commissions / and familiar symphonies.','repertoire.s1 指演奏者或团体准备好可以演出的作品。','乐团准备了新作和经典交响曲。'),C('repertoire.s2','全部技能；一整套办法','Negotiation is one of the mediator’s strongest skills in her professional repertoire.','谈判是这位调解员职业技能库中最擅长的一项。','Negotiation is one skill / in the mediator’s professional repertoire.','repertoire.s2 可指一个人掌握并可运用的技能或方法范围。','调解员的技能库包括谈判。')],M('The orchestra’s repertoire contained no prepared music, so it could not perform any of the listed symphonies.','The orchestra’s repertoire contained prepared symphonies that it could perform.','repertoire 指已准备好可演出的作品，不是没有曲目。','meaning'),[q('What kinds of works were in the orchestra’s repertoire?','new commissions and familiar symphonies','rental agreements and repayment notices','only unfinished songs','乐团准备了新委约作品和熟悉的交响曲。',1,'context'),q('Which skill was in the mediator’s repertoire?','negotiation','repainting','repatriation','谈判是调解员掌握的职业技能。',2,'context'),q('What does repertoire mean for a performer?','the works they are prepared to present','the effects that follow a decision','a single payment made for a job','表演者的 repertoire 指可演出的作品。',1,'meaning'),q('What does repertoire mean in “a repertoire of methods”?','the range of methods available','a list of musical performances only','a building that needs repair','a repertoire of methods 指可运用的一套方法。',2,'meaning')]);
P('repertory','Repertory is related to repertoire and ultimately Latin repertorium, “inventory”; it can mean a theater company’s stock of ready works or a person’s stock of skills.',C('repertory.s1','轮演剧目；储备','The repertory company performed three classic plays in rotation during its spring season.','这家剧目轮演剧团在春季演出季轮番上演三部经典戏剧。','The repertory company performed / three classic plays / in rotation.','repertory.s1 指剧团准备并轮流上演的一批作品，也可指个人的技能储备。','剧团轮流演出常备剧目。'),M('The repertory company had no plays prepared and performed only one new script that it had never rehearsed.','The repertory company performed its prepared plays in rotation.','repertory company 的特点是保有可轮演的剧目。','meaning'),[q('How many classic plays did the company perform in rotation?','three','one hundred','none','剧团轮番演出三部经典戏剧。'),q('When did the repertory company perform them?','during its spring season','after the theater was permanently closed','only during a rehearsal with no audience','剧团在春季演出季轮番演出。',1,'context'),q('What does repertory mean for a theater company?','a stock of prepared works for performance','a payment to repair the theater','a set of repeated warnings','剧团的 repertory 指准备好的轮演剧目。',1,'meaning'),q('What is a repertory of skills?','a person’s available stock of abilities','a single performance of one play','the building where actors live','repertory of skills 指个人掌握的技能储备。',1,'meaning')]);
P('repetition','Repetition comes from Latin repetitio, from repetere “seek again”; it can mean doing something again, practicing for memory, or a repeated section in a work.',[C('repetition.s1','重复（行为/现象）','The repetition of the same billing error across three invoices showed that the software rule needed repair.','同一计费错误在三张发票中重复出现，说明软件规则需要修正。','The repetition of the error / across three invoices / showed a software problem.','repetition.s1 指再次做或出现某事。','同一错误在多张发票中重复。'),C('repetition.s2','反复练习；背诵','Through repetition, the actor memorized the long speech before opening night.','演员通过反复练习，在首演前记住了长篇台词。','Through repetition, the actor memorized / the long speech / before opening night.','repetition.s2 指多次说或做以帮助记忆。','反复练习帮助演员背熟台词。'),C('repetition.s3','重复的部分','The chorus uses repetition of its final line so the audience can sing along.','副歌重复最后一句，让观众可以跟着唱。','The chorus uses repetition / of its final line / so the audience can sing along.','repetition.s3 指歌曲、故事或图案中再次出现的一段。','副歌重复末句方便观众跟唱。')],M('The actor memorized the speech through repetition by reading it once and never practicing it again.','The actor memorized the speech through repetition by practicing it many times.','通过 repetition 记忆需要多次练习，而不是只读一次。','meaning'),[q('What did the repeated billing errors reveal?','the software rule needed repair','the invoices had no repeated content','the customers had learned a long speech','账单重复出错说明软件规则需要修正。',1,'context'),q('How did the actor memorize the speech?','through repeated practice','by canceling the opening night','by repairing three invoices','演员通过反复练习背下台词。',2,'context'),q('Why does the chorus repeat its final line?','so the audience can sing along','to make the play shorter','to remove the melody','副歌重复末句方便观众跟唱。',3,'context'),q('Which meaning is used in “repetition helps learning”?','doing or saying something many times for practice','a repeated section in a song only','a single event that never happens again','repetition helps learning 指反复练习。',2,'meaning')]);
P('repetitious','Repetitious is formed from repetition and -ous; it describes speech or activity repeated so often that it becomes boring.',C('repetitious.s1','反复过多的；冗长乏味的','The reviewer found the lecture repetitious because each section restated the same example without adding evidence.','评论者觉得讲座内容重复乏味，因为每一部分都重述同一个例子，没有增加证据。','The lecture felt repetitious / because each section restated / the same example.','repetitious 描写重复过多、令人厌烦的表达或活动。','讲座多次重复同一例子。'),M('The lecture was repetitious because every section introduced a new topic and never repeated an idea.','The lecture was repetitious because each section restated the same example.','内容不断引入新主题且不重复，不符合 repetitious 的过度重复含义。','meaning'),[q('Why did the reviewer dislike the lecture?','each section repeated the same example','each section added fresh evidence','the lecture ended after one sentence','评论者不满每段都重复同一例子。',1,'context'),q('What does repetitious mean?','repeated so often that it becomes boring','performed only once','worth the effort','repetitious 指重复过多、令人厌烦。',1,'meaning'),q('Which description is repetitious?','a report restating the same point on every page','a report that explains a new finding in each section','a single clear sentence','每页都重述同一点的报告显得冗赘。',1,'context'),q('Which suffix appears in repetitious?','-ous','-er','-able','repetitious 由 repetition 加 -ous 形成。',1,'word-formation')]);
P('repetitive','Repetitive is formed from repeat and -ive; it describes work or activity that becomes boring because the same action is done again and again.',C('repetitive.s1','重复单调的','The repetitive inspection task tired the workers because they checked the same bolt on hundreds of identical units.','这项检查工作十分单调，工人要在数百个相同部件上检查同一颗螺栓。','The inspection task was repetitive / because workers checked / the same bolt on hundreds of units.','repetitive 描写因重复同样动作而显得单调乏味。','工人反复检查大量相同螺栓。'),M('The inspection task was repetitive because every unit required a completely different test and no action was repeated.','The inspection task was repetitive because workers checked the same bolt on every unit.','每件产品都做不同测试且没有重复，不符合 repetitive 的单调重复含义。','meaning'),[q('What did workers check on each unit?','the same bolt','a different bridge design','the theater’s repertory','工人在每个部件上检查同一颗螺栓。',1,'context'),q('Why was the task repetitive?','the same check was done on hundreds of units','every test was completely different','the workers performed one task once','同一检查在数百个部件上重复，因此任务单调。',1,'meaning'),q('Which job sounds repetitive?','scanning the same form all day','solving a different unusual problem each hour','performing one short task once','整天扫描同一表格的工作很重复。',1,'context'),q('Which ending forms the adjective repetitive?','-ive','-ment','-al','repeat 加 -ive 构成 repetitive。',1,'word-formation')]);
P('repetitively','Repetitively is formed from repetitive with -ly; it describes an action done again and again, often at regular intervals.',C('repetitively.s1','反复地；一再地','The warning light flashed repetitively every few seconds until the mechanic found the loose cable.','警示灯每隔几秒就反复闪烁，直到技师找到松动的电缆。','The warning light flashed repetitively / every few seconds / until the cable was fixed.','repetitively 修饰动作，表示重复发生。','警示灯隔几秒反复闪烁。'),M('The warning light flashed repetitively by appearing once and then remaining dark for the rest of the day.','The warning light flashed repetitively by appearing again every few seconds.','只闪一次并保持熄灭不是反复发生。','meaning'),[q('How often did the warning light flash?','again every few seconds','only once that day','only when the cable was removed','警示灯每隔几秒反复闪烁。',1,'context'),q('What does repetitively describe?','an action happening again and again','an action happening only once','an action done in secret','repetitively 表示反复地做某事。',1,'meaning'),q('Which action is done repetitively?','a bell ringing at fixed intervals all morning','a door opening once at noon','a lamp staying off all evening','整上午定时响铃属于反复发生。',1,'context'),q('Which word is the base adjective of repetitively?','repetitive','reported','replaceable','repetitively 由形容词 repetitive 加 -ly 构成。',1,'word-formation')]);
P('rephrase','Rephrase combines re- (“again”) and phrase; it means express an idea again using different words.',C('rephrase.s1','改述；换一种说法','When the first instruction confused the class, the teacher rephrased it with a short example.','第一条指令让全班困惑后，老师用一个简短例子换种说法重新解释。','The teacher rephrased the instruction / with a short example / after students looked confused.','rephrase 指换用不同措辞表达原来的意思。','老师用例子重新表述指令。'),M('The teacher rephrased the instruction by repeating the same sentence word for word without changing its wording.','The teacher rephrased the instruction by explaining the same idea in different words.','逐字原样重复没有换一种措辞表达。','meaning'),[q('Why did the teacher rephrase the instruction?','the class was confused by it','the class had already memorized it','the example had to be removed','学生听不明白，所以老师换种方式表达。',1,'context'),q('What does rephrase mean here?','express the same idea in different words','translate a new idea into numbers','say the same sentence exactly as before','rephrase 是换一种说法表达同一意思。',1,'meaning'),q('Which action rephrases a request?','asking for the same help with different wording','copying the request without edits','changing the topic to a new question','换措辞提出同一个请求属于 rephrase。',1,'context'),q('What stays the same when someone rephrases an idea?','the intended meaning','every original word','the speaker’s accent','改述改变措辞但保留原意。',1,'meaning')]);
P('replace','Replace comes through Old French replacier from re- and place; it means put a substitute in a position, take another person’s role, or put something back where it belongs.',[C('replace.s1','替换；代替','The caretaker replaced the cracked window with a new pane before the next storm.','下一场暴风雨前，管理员用新玻璃片换掉了破裂的窗玻璃。','The caretaker replaced the cracked pane / with a new one / before the storm.','replace.s1 指用新事物替代旧事物。','破裂玻璃被新玻璃替换。'),C('replace.s2','接替；取代某人的职位','A deputy will replace the director during her two-week medical leave.','主任休两周病假期间，由副主任接替她。','A deputy will replace the director / during her medical leave / for two weeks.','replace.s2 指接替某人的工作或角色。','副主任暂时代替主任。'),C('replace.s3','放回原处','After using the microscope, please replace the dust cover before leaving the lab.','显微镜使用完后，离开实验室前请把防尘罩放回原处。','Please replace the dust cover / after using the microscope / before leaving the lab.','replace.s3 指把物品放回原来位置。','使用后将防尘罩放回去。')],M('The caretaker replaced the cracked pane by leaving the broken glass in the frame and adding no substitute.','The caretaker replaced the cracked pane by fitting a new pane in its place.','replace 作替换义时必须以新物件取代旧物件。','meaning'),[q('What did the caretaker put in place of the cracked pane?','a new window pane','the director’s medical leave','the microscope cover','管理员换上了一块新玻璃。',1,'context'),q('Who will take the director’s role while she is away?','a deputy','the caretaker','a laboratory visitor','副主任将在主任休假时接替她。',2,'context'),q('What should be done with the dust cover?','put it back in its usual place','use it as a new window pane','give it to the deputy','离开实验室前要把防尘罩放回原处。',3,'context'),q('In “a deputy will replace the director,” what does replace mean?','take over another person’s role','repair a cracked object','return an object to a shelf','这里 replace 指接替主任的职位。',2,'meaning')]);
P('replaceable','Replaceable is formed from replace and -able; it describes a person or thing that can be substituted by another.',C('replaceable.s1','可替代的','The standard battery is replaceable, so users can install a fresh one instead of discarding the whole device.','这种标准电池可以更换，用户可装入新电池，不必丢掉整台设备。','The battery is replaceable / so users can install a fresh one / in the same device.','replaceable 指可以由另一人或物替代的。','电池可单独更换。','-able 表示“能够……的”。'),M('The battery is replaceable because no other battery can fit the device and the entire device must be discarded.','The battery is replaceable because another battery of the standard size can take its place.','若没有任何替代电池且必须丢弃整机，就不能说电池可替代。','meaning'),[q('What can users do because the battery is replaceable?','install a fresh battery','discard every device part','replace the whole neighborhood','用户可以装入新电池，而不必丢弃整机。',1,'context'),q('What does replaceable mean?','able to be substituted by another','already used up and impossible to change','belonging to a report','replaceable 表示可由其他事物替代。',1,'meaning'),q('Which item is replaceable?','a standard filter that can be swapped for a new one','a unique key with no duplicate','a stone fixed permanently into a wall','可用新滤芯替换的滤芯属于 replaceable。',1,'context'),q('Which suffix in replaceable conveys possibility?','-able','-ment','-ly','replace 加 -able 表示“可以替换的”。',1,'word-formation')]);
P('replacement','Replacement comes from replace plus -ment; it means a person or thing taking another’s place, or the act of putting a substitute in place.',C('replacement.s1','替代者；替换物；替换','The museum ordered a replacement for the cracked display case and kept the damaged one for inspection.','博物馆为破裂的展柜订购了替换品，并留下受损展柜供检查。','The museum ordered a replacement / for the cracked case / and kept the damaged one.','replacement 可指取代旧物的新物件，也可指替换这一行为。','博物馆订购新展柜来替换破损展柜。'),M('The museum ordered a replacement for the cracked case, but the order was a report about the damage and supplied no substitute.','The museum ordered a replacement: a new display case to take the cracked case’s place.','只有损坏报告而没有替代物，不是 replacement。','meaning'),[q('What did the museum order?','a new display case','a new museum director','a report about a warning light','博物馆订购了新的展柜来替换破损展柜。',1,'context'),q('What does replacement refer to in this sentence?','a thing taking the cracked case’s place','the act of rephrasing an instruction','a device flashing repeatedly','此处 replacement 指替换破损展柜的新展柜。',1,'meaning'),q('Which event is a replacement?','installing a new pump where the broken pump was','writing a report about a broken pump only','putting the broken pump back without repair','在坏泵的位置装上新泵属于 replacement。',1,'context'),q('Which ending appears in the noun replacement?','-ment','-able','-er','replacement 由 replace 加名词后缀 -ment 构成。',1,'word-formation')]);
P('replant','Replant combines re- and plant; it means plant something again or establish plants in a place once more.',C('replant.s1','重新种植；补种','Volunteers will replant native trees along the riverbank after the flood-control work is finished.','防洪工程结束后，志愿者将在河岸重新种植本地树种。','Volunteers will replant native trees / along the riverbank / after the construction work.','replant 指再次把植物种入土中，常用于补种或恢复植被。','河岸工程后补种本地树木。'),M('Volunteers replanted the riverbank by removing every tree and leaving the cleared ground bare.','Volunteers replanted the riverbank by putting young native trees into the cleared soil.','清除树木并让地面裸露是砍伐，不是重新种植。','meaning'),[q('Where will volunteers replant trees?','along the riverbank','inside the museum display case','around the laboratory microscope','志愿者将在河岸补种树木。',1,'context'),q('What does replant mean?','plant again in a place','remove plants and keep the soil bare','replace a person in a job','replant 指重新种植植物。',1,'meaning'),q('Which action is replanting?','putting young trees into soil after construction','cutting down the last tree and planting none','ordering a replacement glass pane','工程后把幼树种回土里属于 replant。',1,'context'),q('What does the prefix re- contribute to replant?','again','without','before','re- 在 replant 中表示“再次”。',1,'word-formation')]);
P('replay','Replay combines re- and play; it means play a recording, game, or event again.',C('replay.s1','重放；重播','The referee asked the stadium operator to replay the final camera angle before confirming the goal.','确认进球前，裁判让体育场操作员重放最后一个摄像角度。','The operator replayed the final camera angle / before the referee / confirmed the goal.','replay 指再次播放已录制的画面、声音或赛事。','裁判要求重放录像画面。'),M('The operator replayed the camera angle by deleting the recording and refusing to show it again.','The operator replayed the camera angle by playing the recording a second time.','删除录像且不再播放，与 replay 的再次播放意思相反。','meaning'),[q('What did the operator replay?','the final camera angle','the cracked display case','the riverbank trees','操作员重放了最后一个摄像角度。',1,'context'),q('Why did the referee request a replay?','to review the recorded angle before confirming the goal','to plant trees after flood work','to replace a director during leave','裁判要查看重放画面后再确认进球。',1,'context'),q('What does replay mean?','play a recording or event again','play something for the first time only','return a cover to its shelf','replay 指再次播放。',1,'meaning'),q('Which action is a replay?','watching the same recorded finish a second time','watching a live race for the first time','turning off a camera before recording','第二次观看同一段赛事录像属于 replay。',1,'context')]);
P('replenish','Replenish came through Old French repleniss- from Latin replere, “fill again”; it means make a supply full again or become full again.',[C('replenish.s1','补充；重新装满','The field team replenished its water supply at the village well before returning to the dry trail.','野外小组在返回干燥山路前，到村井补充了饮用水。','The field team replenished its water / at the village well / before returning to the trail.','replenish.s1 是及物用法，指补足已消耗的供应。','小组重新补充饮用水。'),C('replenish.s2','补足；重新充满','After the rain, the reservoir began to replenish as water flowed down from the hills.','降雨后，山上的水流下来，水库开始重新蓄满。','The reservoir began to replenish / after the rain / as water flowed from the hills.','replenish.s2 指某种供应或储量再次充足。','降雨使水库重新蓄水。')],M('The team replenished its water supply by pouring out its last bottle and carrying no replacement water.','The team replenished its water supply by filling its containers again at the village well.','倒掉最后一瓶水且不补充，会减少而非补足供应。','meaning'),[q('Where did the team replenish its water?','at the village well','at the dry trail’s end with no water','inside the museum','小组在村井补充饮用水。',1,'context'),q('What happened to the reservoir after rain?','it began to fill again','it was emptied by the field team','it was replayed on camera','水库在降雨后开始重新蓄满。',2,'context'),q('What does replenish a supply mean?','make it full again','use it up without adding more','report its size to an official','replenish a supply 就是把消耗的储备补足。',1,'meaning'),q('Which phrase best matches the Latin source replere?','fill again','fold back','take a role','replere 的意思是“再填满”。',1,'word-formation')]);
P('replenishment','Replenishment is formed from replenish and -ment; it means the act of restoring a supply or the goods used to restore it.',[C('replenishment.s1','补充；补足','The replenishment of the clinic’s emergency kits took place before the storm season began.','风暴季开始前，诊所补充了急救包物资。','The replenishment of the emergency kits / took place / before storm season.','replenishment.s1 指补充储备的行为或过程。','诊所补足了急救包。'),C('replenishment.s2','补给品；补充物资','A delivery of replacement filters arrived as replenishment for the treatment plant’s depleted stock.','一批替换滤芯送到，作为水处理厂耗尽库存的补给。','Replacement filters arrived / as replenishment / for the depleted stock.','replenishment.s2 可指用来恢复库存的补给物资。','新滤芯补足了耗尽的库存。')],M('The replenishment of the kits consisted of removing their remaining bandages and adding nothing to the stock.','The replenishment of the kits consisted of adding fresh bandages and antiseptic supplies.','拿走剩余物品且不补新货不是补充库存。','meaning'),[q('When were the clinic kits replenished?','before storm season','after the filters were discarded','during the riverbank planting','诊所在风暴季到来前补充了急救包。',1,'context'),q('What arrived as replenishment for the plant?','replacement filters','the emergency kits','a camera replay','新滤芯作为水处理厂的补给送达。',2,'context'),q('Which meaning does replenishment have in “the replenishment took place”?','the act of restoring a supply','a person who replaces a director','a recording played again','这里 replenishment 指补充储备的过程。',1,'meaning'),q('What does the suffix -ment do in replenishment?','forms a noun for an act or result','means “in a repeated way”','marks a person who reports news','-ment 把 replenish 变成表示行为或结果的名词。',1,'word-formation')]);
P('replica','Replica came from Italian replica, related to Latin replicare (“repeat”); it means an accurate copy of an original.',C('replica.s1','复制品；仿制品','The gallery displayed a replica of the ancient bowl so visitors could examine its design without handling the fragile original.','展厅展出了一只古碗的复制品，让参观者研究其造型而不触碰易碎的原件。','The gallery displayed a replica / so visitors could study the design / without handling the original.','replica 指根据原物制作、外观或细节相似的复制品。','复制品供观众观察，原件得到保护。'),M('The gallery labeled a newly designed bowl a replica even though it copied no existing object.','The gallery labeled the bowl a replica because it accurately copied the ancient original.','没有仿照任何原物的新设计不是复制品。','meaning'),[q('Why did the gallery use a replica?','to let visitors inspect the design without handling the fragile original','to replace the riverbank trees','to replay the goal camera angle','复制品让观众查看造型，同时保护易碎原件。',1,'context'),q('What is a replica?','an accurate copy of an original','a supply that is filled again','a report made by a journalist','replica 指原物的精确复制品。',1,'meaning'),q('Which object is a replica?','a carefully copied model of an old ship','a new design with no original model','a broken original left unrepaired','仿照旧船精心制作的模型属于 replica。',1,'context'),q('Which older word is linked to replica’s origin?','replicare, “repeat”','replere, “fill”','reportare, “carry back”','replica 与拉丁语 replicare（重复）有关。',1,'word-formation')]);
P('replicate','Replicate comes from Latin replicare, “fold back” or “repeat”; it means make a copy, repeat a procedure, or reproduce biologically.',[C('replicate.s1','复制；仿制','The lab can replicate the ceramic fragment with a 3-D printer for use in the teaching collection.','实验室可以用3D打印机复制这块陶瓷碎片，供教学藏品使用。','The lab can replicate the fragment / with a 3-D printer / for teaching.','replicate.s1 指制作某物的复制品。','实验室打印碎片仿制品。'),C('replicate.s2','重复实验；复现','A second research group replicated the trial using the same temperature, sample size, and timing.','第二个研究小组采用相同的温度、样本量和时间重复了这项试验。','A second group replicated the trial / using the same conditions / and sample size.','replicate.s2 指按相同条件重复实验或过程。','研究人员按同样条件重复试验。'),C('replicate.s3','复制；自我繁殖','The virus needs a host cell in order to replicate and produce more copies of its genetic material.','这种病毒需要宿主细胞才能复制并产生更多遗传物质。','The virus needs a host cell / in order to replicate / its genetic material.','replicate.s3 可指细胞或病毒复制遗传物质。','病毒在宿主细胞内复制。')],M('The research group replicated the trial by changing the temperature and sample size at every stage.','The research group replicated the trial by repeating it under the same conditions.','每个阶段都更改关键条件，不能称为按同样条件复现实验。','meaning'),[q('What will the lab make with its 3-D printer?','a copy of the ceramic fragment','a new virus host cell','a replacement director','实验室将打印陶瓷碎片的复制品。',1,'context'),q('How did the second group replicate the trial?','by using the same conditions and sample size','by changing every condition','by putting the microscope cover back','第二组用相同条件和样本量重复试验。',2,'context'),q('What does the virus replicate inside a host cell?','its genetic material','the ceramic display case','a journalist’s report','病毒在宿主细胞中复制遗传物质。',3,'context'),q('Which use of replicate means repeat an experiment?','The team replicated the trial under the original conditions.','The virus replicated its genetic material in a cell.','The printer replicated the bowl for display.','第一句中的 replicate 指按原条件重复试验。',1,'meaning')]);
P('replication','Replication is from Latin replicatio, from replicare (“repeat”); it means the making of a copy, especially of DNA or an experimental result.',C('replication.s1','复制；复现','The researchers checked DNA replication by comparing the copied strands with the original sequence.','研究人员通过将复制链与原始序列比较来检查DNA复制。','The researchers checked DNA replication / by comparing copied strands / with the original sequence.','replication.s1 指复制原有材料，尤用于DNA或实验结果。','研究人员核对DNA复制后的链。'),M('The researchers called it DNA replication even though no genetic material was copied and the original strand was simply stored.','The researchers called it DNA replication because the genetic sequence was copied into new strands.','没有复制遗传物质就不是DNA复制。','meaning'),[q('What did researchers compare to check replication?','the copied strands and the original sequence','two replacement window panes','the clinic’s emergency kits','研究人员比较复制链与原始序列。',1,'context'),q('What is DNA replication?','copying genetic material','returning a cover to a shelf','repeating a reporter’s sentence with new wording','DNA replication 指遗传物质的复制。',1,'meaning'),q('Which process is replication?','making a new DNA strand from an existing sequence','discarding an original sample without copying it','replanting trees after construction','根据原有序列形成新DNA链属于 replication。',1,'context'),q('Which verb is the source of replication?','replicate','replay','repose','replication 来自动词 replicate。',1,'word-formation')]);
P('reply','Reply comes through Old French replier from Latin replicare, “fold back”; as a verb it means answer, and as a noun it means an answer.',[C('reply.s1','回答；答复','Please reply to the invitation by Friday so the organizers can confirm the number of seats.','请在周五前回复邀请，以便组织者确认座位数量。','Please reply to the invitation / by Friday / so the organizers can confirm seats.','reply.s1 作动词，表示回答或答复。','受邀者需要在周五前答复。'),C('reply.s2','回答；答复','Her reply to the editor explained why the revised chart used a different scale.','她给编辑的答复解释了修订后的图表为何使用不同刻度。','Her reply to the editor / explained the revised chart’s / different scale.','reply.s2 作名词，表示回答或答复本身。','答复中说明了图表刻度的变化。')],M('Please reply to the invitation by Friday by ignoring it and sending no answer to the organizers.','Please reply to the invitation by Friday by sending the organizers an answer.','不发送任何答复不符合 reply 的回答含义。','meaning'),[q('By when should the invitation be answered?','Friday','the start of storm season','the next microscope inspection','受邀者应在周五前回复。',1,'context'),q('What did her reply explain?','why the revised chart used a different scale','why the riverbank was replanted','how a virus copied its DNA','她的答复解释了修订图表使用不同刻度的原因。',2,'context'),q('In “please reply,” which part of speech is reply?','verb','noun naming an answer','adjective describing a copy','please reply 中 reply 是动词。',1,'meaning'),q('In “her reply,” what does reply name?','the answer she gave','the act of planting trees','a copy of the ancient bowl','her reply 指她给出的答复。',1,'meaning')]);
P('report','Report came through Old French reporter from Latin reportare, “carry back”; it can mean an account, the act of giving information to an authority, or a formal notification.',[C('report.s1','报告；报道；记录','The annual report summarizes the museum’s attendance, spending, and conservation work.','年度报告总结了博物馆的参观人数、支出和文物保护工作。','The annual report summarizes / attendance and spending / for the museum.','report.s1 指书面或口头呈现事实的报告。','年度报告概述博物馆运营情况。'),C('report.s2','报到；报告','New volunteers must report to the front desk at 8 a.m. for their safety briefing.','新志愿者必须早上八点到前台报到并参加安全说明会。','New volunteers must report to the front desk / at 8 a.m. / for a safety briefing.','report.s2 指按要求到某处报到或履职。','志愿者需到前台报到。'),C('report.s3','举报；报告问题','Residents can report a leaking pipe to the water authority through its online form.','居民可通过水务部门的在线表格报告漏水管道。','Residents can report a leaking pipe / to the water authority / through an online form.','report.s3 指向负责机构报告问题或违规事件。','居民向水务部门报告漏水。')],M('Residents reported the leaking pipe by keeping the damage secret and sending no information to the water authority.','Residents reported the leaking pipe by notifying the water authority through its online form.','不告知负责部门就不是向其报告问题。','meaning'),[q('What does the annual report summarize?','attendance, spending, and conservation work','the volunteers’ replies to invitations','the DNA of the water pipes','年度报告总结参观人数、支出和保护工作。',1,'context'),q('Where must new volunteers report at 8 a.m.?','the front desk','the riverbank','the research laboratory','新志愿者要到前台报到。',2,'context'),q('Who should receive a report about a leaking pipe?','the water authority','the museum visitors','the gallery’s camera operator','漏水问题应报告给水务部门。',3,'context'),q('In “the report summarizes spending,” what does report mean?','an account of information','arriving at a workplace','notifying an authority about a leak','这里 report 是对信息的书面总结。',1,'meaning')]);
P('reported','Reported is the past participle of report; as an adjective it describes information known from accounts rather than direct observation.',C('reported.s1','据报道的；传闻的','The reported delay was not confirmed by the railway, so passengers were advised to check the live schedule.','铁路部门未证实这一据报延误，因此乘客被建议查看实时班次表。','The reported delay / was not confirmed / by the railway.','reported 可表示某事来自报告或消息来源，尚未由说话者亲自证实。','铁路尚未证实据报的延误。'),M('The reported delay was described as reported even though railway staff directly observed and officially confirmed it at the station.','The reported delay was described as reported because it came from unconfirmed accounts.','已亲自观察并正式确认的消息不是单纯据报的信息。','meaning'),[q('Did the railway confirm the delay?','no, it was not confirmed','yes, it issued a final confirmation','the delay was replaced by a replica','铁路没有证实这一据报延误。',1,'context'),q('What does reported suggest here?','the information came from accounts and may need checking','the speaker personally verified every detail','the train has been replaced','reported 暗示信息来自报道或消息来源。',1,'meaning'),q('Which statement is a reported claim?','A news account says the bridge may close, but officials have not confirmed it.','An inspector confirms the bridge is open after checking it.','A reporter repairs the bridge personally.','尚未获官方确认的新闻说法属于 reported claim。',1,'context'),q('Which verb forms reported?','report','replant','replay','reported 是 report 的过去分词形式。',1,'word-formation')]);
P('reportedly','Reportedly is formed from reported and -ly; it means according to reports or what other people have said, without claiming firsthand certainty.',C('reportedly.s1','据报道；据说','The reportedly rare manuscript is being examined by specialists, although the library has not yet authenticated it.','据说这份手稿十分罕见，专家正在检查，但图书馆尚未确认其真伪。','The manuscript is reportedly rare / although specialists are examining it / and authentication is pending.','reportedly 标明信息据报道或他人所说，常保留不确定性。','图书馆尚未鉴定据说罕见的手稿。'),M('The manuscript was reportedly rare because the speaker personally authenticated it and stated that no reports were involved.','The manuscript was reportedly rare because the claim came from accounts that the library had not confirmed.','亲自鉴定并排除传闻来源，不符合 reportedly 的传闻语气。','meaning'),[q('What is still pending for the manuscript?','authentication by the library','replanting the library garden','a camera replay','图书馆尚未确认手稿真伪。',1,'context'),q('What does reportedly signal?','the claim comes from reports rather than firsthand certainty','the speaker has personally proved the claim','the information is a replacement item','reportedly 表示信息据报道或据说。',1,'meaning'),q('Which sentence uses reportedly appropriately?','The reportedly damaged bridge is still awaiting an official inspection.','I personally inspected the bridge and know with certainty it is reportedly open.','The bridge reportedly replaced the inspector.','尚待官方检查的桥梁情况可用 reportedly 表示消息来源。',1,'context'),q('What does -ly add to reported in reportedly?','an adverbial “according to reports” sense','a noun meaning a report writer','a past-tense verb meaning repaired','reportedly 是由 reported 加 -ly 构成的副词。',1,'word-formation')]);
P('reporter','Reporter is formed from report and the agent suffix -er; it means a person who gathers or presents news or information.',C('reporter.s1','记者；报道者','The reporter interviewed residents near the flood barrier and checked the water authority’s public records.','记者采访了防洪堤附近的居民，并查阅水务部门的公开记录。','The reporter interviewed residents / near the flood barrier / and checked public records.','reporter 指采集、核实并报道新闻的人。','记者采访居民并查阅记录。'),M('The reporter gathered no information or interviews and spent the day silently replacing a museum window.','The reporter interviewed residents and checked records before writing the news story.','记者需要采集或呈现信息，单纯修窗并非记者工作。','meaning'),[q('Whom did the reporter interview?','residents near the flood barrier','the museum’s replica makers','the clinic’s volunteers','记者采访了防洪堤附近的居民。',1,'context'),q('What else did the reporter check?','the water authority’s public records','the library’s unverified manuscript only','the microscope’s dust cover','记者还查阅了水务部门公开记录。',1,'context'),q('What is a reporter?','a person who gathers or presents news','a place where emergency supplies are stored','a new object replacing a broken one','reporter 是采集或报道新闻的人。',1,'meaning'),q('Which suffix marks a person who performs an action?','-er','-ment','-ly','report 加 -er 构成表示从业者的 reporter。',1,'word-formation')]);
P('repose','Repose came through Old French reposer from Latin reponere, “put back”; it means rest or calm, and can describe a peaceful position or manner.',C('repose.s1','休息；宁静；安详','After the long crossing, the crew found repose in a quiet room overlooking the harbor.','长途航行后，船员在一间俯瞰港口的安静房间里得以休息。','The crew found repose / in a quiet room / after the long crossing.','repose 指休息、平静或安宁的状态。','船员在安静房间里休息。'),M('The exhausted crew found repose by continuing the crossing without stopping and staying in a noisy engine room.','The exhausted crew found repose by resting in the quiet harbor room.','持续工作且身处嘈杂环境不是休息或宁静。','meaning'),[q('Where did the crew find repose?','in a quiet room overlooking the harbor','on the flood barrier during an interview','in the laboratory beside a running alarm','船员在俯瞰港口的安静房间里休息。',1,'context'),q('What does repose mean in this context?','rest or calm','a report to an authority','an exact copy','repose 指休息或宁静。',1,'meaning'),q('Which scene conveys repose?','a traveler resting quietly after a long journey','a warning light flashing every few seconds','a team rushing to replace a broken pane','长途旅行后安静休息的场景体现 repose。',1,'context'),q('Which Latin verb is linked to the history of repose?','reponere, “put back”','replere, “fill again”','reportare, “carry back”','repose 的词源与 reponere（放回）有关。',1,'word-formation')]);
P('repository','Repository comes from Latin repositorium, from reponere (“put back”); it means a place or system where things are stored for later use.',C('repository.s1','存放处；资料库','The university repository stores digitized field notes so researchers can search them years after a project ends.','大学资料库保存数字化的田野笔记，研究人员可在项目结束多年后检索。','The university repository stores field notes / in digitized form / for later research.','repository 指保存物品或信息、供日后取用的地方或系统。','数字资料库保存研究笔记。'),M('The university repository was a place where every file was immediately erased and could never be retrieved later.','The university repository stored files so researchers could retrieve them later.','文件被立即删除且不能取回的地方不是存储库。','meaning'),[q('What does the university repository store?','digitized field notes','replacement window panes','the reporter’s live interviews only','大学资料库保存数字化田野笔记。',1,'context'),q('Why are the notes kept there?','so researchers can search them later','so they can be erased immediately','so volunteers can replant them','资料库让研究人员日后检索笔记。',1,'context'),q('What is a repository?','a place or system for storing things for later use','a person who gathers news','a repeated camera recording','repository 是供日后使用的存储处或系统。',1,'meaning'),q('What does the Latin source reponere contribute to repository’s history?','the idea of putting something back or storing it','the idea of speaking with new words','the idea of filling a tank','repository 的词源包含“放回、存放”的概念。',1,'word-formation')]);
P('repossess','Repossess combines re- and possess; it means take back property, typically when a buyer fails to make required payments.',C('repossess.s1','收回；依法收回抵押物','After the buyer missed several payments, the lender followed the contract and repossessed the car.','买方拖欠数期款项后，贷款方按合同收回了汽车。','The lender repossessed the car / after several missed payments / under the contract.','repossess 常指因未按约付款而收回已售或抵押财物。','买方拖欠款项后，贷款方收回汽车。'),M('The lender repossessed the car by forgiving the unpaid balance and permanently giving the buyer full ownership.','The lender repossessed the car by taking it back after the buyer missed required payments.','免除欠款并让买家继续拥有车辆，与收回财物相反。','meaning'),[q('Why did the lender repossess the car?','the buyer missed several payments','the buyer asked for a camera replay','the car was a replica on display','买方拖欠数期款项，因此贷款方收回汽车。',1,'context'),q('What does repossess mean?','take back property, often after missed payments','repair a damaged object','store files for future use','repossess 指收回财物，常因未按期付款。',1,'meaning'),q('Which situation can lead a lender to repossess an item?','the borrower stops making required payments','the borrower replies to an invitation','the borrower replants a garden','借款人停止按约付款可能导致财物被收回。',1,'context'),q('What does the prefix re- suggest in repossess?','taking back again','making an exact copy','doing something repetitively','re- 在 repossess 中含有“重新取回”的意思。',1,'word-formation')]);
})();
